(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).mk={"1":{"1":"Աստծու Որդու՝ Հիսուս Քրիստոսի Ավետարանի սկիզբը։","2":"Ինչպես գրել են մարգարեները. «Ահա ես իմ հրեշտակին ուղարկում եմ քո առաջից, որ քո ճանապարհը պատրաստի քո առաջ» (Մղք. 3.1)։","3":"«Անապատում կանչողի ձայնն է. \"Տիրոջ ճանապա՛րհը պատրաստեք ու նրա շավիղներն ուղի՛ղ արեք\"» (Ես. 40.3)։","4":"Հովհաննեսն անապատում մկրտում էր ու մեղքերի թողության համար ապաշխարության մկրտություն քարոզում։","5":"Նրա մոտ էին գնում Հրեաստանի բոլոր բնակիչները և երուսաղեմցիները։ Նրանք Հորդանան գետում Հովհաննեսից մկրտվում էին՝ իրենց մեղքերը խոստովանելով։","6":"Հովհաննեսն ուղտի մազից հագուստ էր հագել, կաշվե գոտի ուներ իր մեջքին, մորեխ ու վայրի մեղր էր ուտում։","7":"Եվ քարոզելով ասում էր. «Իմ հետևից գալիս է ինձանից ավելի զորավորը, որին ես արժանի չեմ խոնարհվելու և կոշիկների կապերն արձակելու։","8":"Ես ձեզ ջրով մկրտեցի, բայց նա Սուրբ Հոգով կմկրտի ձեզ»։","9":"Այն օրերին Հիսուսը Գալիլեայի Նազարեթից եկավ և Հորդանանում Հովհաննեսի ձեռքով մկրտվեց։","10":"Եվ անմիջապես, երբ ջրից դուրս էր գալիս, տեսավ երկինքը ճեղքված ու Աստծու Հոգին, որ աղավնակերպ իր վրա էր իջնում։","11":"Եվ երկնքից ձայն լսվեց. «Դու ես իմ սիրելի Որդին, որ ունի իմ բարեհաճությունը»։","12":"Եվ իսկույն Հոգին նրան անապատ տարավ։","13":"Նա այնտեղ մնաց քառասուն օր և սատանայից փորձության ենթարկվեց. ապրում էր գազանների հետ, ու հրեշտակները ծառայում էին նրան։","14":"Հովհաննեսի մատնվելուց հետո Հիսուսը եկավ Գալիլեա. քարոզում էր Աստծու թագավորության Ավետարանն","15":"ու ասում. «Լրացել է ժամանակը, և մոտեցել է Աստծու թագավորությունը. ապաշխարե՛ք ու հավատացե՛ք Ավետարանին»։","16":"Գալիլեայի լճափով անցնելիս տեսավ Սիմոնին ու նրա եղբայր Անդրեասին, որոնք լճի մեջ ուռկան էին գցում, որովհետև ձկնորս էին։","17":"Հիսուսը նրանց ասաց. «Իմ հետևի՛ց եկեք, ու ես ձեզ մարդկա՛նց որսորդներ կդարձնեմ»։","18":"Նրանք անմիջապես իրենց ուռկանները թողեցին ու նրան հետևեցին։","19":"Փոքր-ինչ առաջանալով՝ տեսավ Զեբեդեոսի որդի Հակոբոսին ու նրա եղբայր Հովհաննեսին, որոնք ևս նավի վրա ուռկաններ էին կարգի բերում.","20":"նրանց էլ իսկույն կանչեց։ Նրանք, իրենց հորը՝ Զեբեդեոսին, վարձու աշխատողների հետ նավի վրա թողնելով, նրան հետևեցին։","21":"Եվ մտան Կափառնաում։ Հենց շաբաթ օրը նա ժողովարան մտավ և ուսուցանում էր։","22":"Եվ նրա ուսուցման վրա զարմանում էին, որովհետև իբրև իշխանություն ունեցող էր ուսուցանում նրանց, այլ ոչ թե դպիրների պես։","23":"Ժողովարանում պիղծ ոգով բռնված մի մարդ կար. նա աղաղակեց","24":"ու ասաց. «Ի՞նչ գործ ունես մեզ հետ, Հիսո՛ւս Նազովրեցի։ Մեզ կորստյան մատնելո՞ւ եկար։ Գիտեմ քեզ, թե ով ես. Աստծու Սուրբը»։","25":"Հիսուսը նրան սաստեց ու ասաց. «Պապանձվի՛ր և դրա միջից դո՛ւրս արի»։","26":"Պիղծ ոգին նրան սաստիկ թափահարեց ու բարձրաձայն գոչելով՝ նրա միջից դուրս եկավ։","27":"Բոլորը զարմացան. իրար մեջ խոսում էին ու ասում. «Սա ի՞նչ է, ի՞նչ նոր ուսուցում է, որ իշխանությամբ պիղծ ոգիներին էլ է սաստում, ու հնազանդվում են նրան»։","28":"Եվ նրա համբավն անմիջապես տարածվեց Գալիլեայի բոլոր կողմերում։","29":"Ժողովարանից անմիջապես դուրս գալով՝ Հակոբոսի ու Հովհաննեսի հետ Սիմոնի ու Անդրեասի տուն եկան։","30":"Սիմոնի զոքանչը տենդի մեջ պառկած էր։ Իսկույն նրա մասին ասացին Հիսուսին։","31":"Նա մոտեցավ, ձեռքից բռնելով նրան ոտքի կանգնեցրեց, և տենդն իսկույն թողեց նրան։ Եվ ծառայում էր նրանց։","32":"Երբ երեկո եղավ, արեգակի մայր մտնելու ժամանակ բոլոր հիվանդներին և դիվահարներին նրա մոտ բերեցին։","33":"Քաղաքի բոլոր բնակիչները դռան առաջ էին հավաքվել։","34":"Տարբեր ցավերով տառապող շատ հիվանդների բժշկեց ու շատ դևեր հանեց։ Եվ դևերին թույլ չէր տալիս, որ խոսեին, որովհետև նրան գիտեին։","35":"Վաղ առավոտյան՝ լույսը դեռ չբացված, վեր կացավ, դուրս եկավ, մի ամայի տեղ գնաց ու այնտեղ աղոթում էր։","36":"Սիմոնն ու նրա հետ եղողները նրա հետևից գնացին։","37":"Եվ երբ նրան գտան, ասացին. «Բոլորը քեզ են փնտրում»։","38":"Նրանց ասաց. «Մոտակա գյուղաքաղաքները գնանք, որ այնտեղ էլ քարոզեմ, որովհետև դրա համար եմ եկել»։","39":"Եվ ամբողջ Գալիլեայով մեկ նրանց ժողովարաններում քարոզում էր ու դևերին հանում։","40":"Հիսուսի մոտ մի բորոտ եկավ. ծնկի իջած աղաչում էր և ասում. «Եթե ուզես, կարող ես ինձ մաքրել»։","41":"Հիսուսը գթալով ձեռքը մեկնեց, նրան դիպավ ու ասաց. «Ուզում եմ, մաքրվի՛ր»։","42":"Երբ ասաց նրան, բորոտությունն իսկույն վերացավ նրա վրայից, և նա մաքրվեց։","43":"Եվ նրան անմիջապես դուրս հանելով՝ հորդորեց ու","44":"ասաց. «Զգո՛ւյշ կաց, ոչ ոքի ոչինչ չասես, այլ գնա՛, քեզ ցո՛ւյց տուր քահանային ու քո մաքրվելու համար մատուցի՛ր այն, ինչ Մովսեսն է հրամայել՝ որպես դրա վկայություն»։","45":"Իսկ նա, դուրս գնալով, սկսեց այդ ամենը պատմել ու տարածել, այնպես որ Հիսուսն այլևս չէր կարողանում բացահայտ մտնել քաղաք, այլ դրսում՝ ամայի տեղերում էր լինում։ Եվ ժողովուրդը բոլոր կողմերից նրա մոտ էր գալիս։"},"2":{"1":"Օրեր անց Հիսուսը դարձյալ Կափառնաում մտավ։ Լուր տարածվեց, որ մեկի տանն է։","2":"Անմիջապես այնքան շատ մարդիկ հավաքվեցին, որ դռան մոտ նույնիսկ տեղ չկար։ Եվ նա Աստծու խոսքն էր քարոզում նրանց։","3":"Եվ նրա մոտ բերեցին մի անդամալույծի, որին բռնել էին չորս հոգով։","4":"Երբ ամբոխի պատճառով Հիսուսին մոտենալ չկարողացան, քանդեցին այն տան տանիքը, որտեղ նա էր, և անցք բաց անելով՝ իջեցրին մահիճը, որի վրա պառկած էր անդամալույծը։","5":"Հիսուսը, նրանց հավատը տեսնելով, անդամալույծին ասաց. «Որդյա՛կ, քո մեղքերը քեզ ներված են»։","6":"Դպիրներից ոմանք նստած էին այնտեղ և իրենց մեջ մտածում էին.","7":"«Ինչպե՞ս է սա այդպես խոսում. հայհոյում է։ Ո՞վ կարող է մեղքերին թողություն տալ, եթե ոչ միայն մեկը՝ Աստված»։","8":"Եվ Հիսուսն իսկույն իր հոգում իմացավ, որ իրենց մտքում այդպես են մտածում, և նրանց ասաց. «Ինչո՞ւ եք ձեր մտքում նման բաներ մտածում։","9":"Ո՞րն է հեշտ. անդամալույծին ասել՝ \"Քո մեղքերը ներված են քեզ\", թե՞ ասել՝ \"Վե՛ր կաց, մահիճդ վերցրո՛ւ և քայլի՛ր\"։","10":"Բայց որպեսզի իմանաք, որ Մարդու Որդին երկրի վրա մեղքերին թողություն տալու իշխանություն ունի (անդամալույծին ասաց),","11":"ասում եմ քեզ՝ վե՛ր կաց, մահիճդ վերցրո՛ւ, քո տո՛ւն գնա»։","12":"Եվ սա իսկույն վեր կացավ, մահիճը վերցրեց ու բոլորի առաջ դուրս գնաց, մինչ բոլորը զարմանում էին ու Աստծուն փառաբանում՝ ասելով. «Այսպիսի բան երբեք չենք տեսել»։","13":"Եվ դարձյալ գնաց դեպի լճի եզերքը. ամբողջ ժողովուրդը նրա մոտ էր գալիս, և նա ուսուցանում էր նրանց։","14":"Անցնելիս տեսավ Ալփեոսի որդի Ղևիին՝ մաքսատանը նստած, ու նրան ասաց. «Իմ հետևի՛ց արի»։ Եվ նա վեր կացավ ու գնաց Հիսուսի հետևից։","15":"Եվ երբ նրա տանը սեղան էր նստել, շատ մաքսավորներ ու մեղավորներ էին Հիսուսի ու նրա աշակերտների հետ ճաշի նստել, որովհետև շատ մարդիկ էին նրա հետևից գնում։","16":"Բայց դպիրներն ու փարիսեցիները, տեսնելով, որ ուտում է մաքսավորների ու մեղավորների հետ, նրա աշակերտներին ասացին. «Ինչո՞ւ է մաքսավորների ու մեղավորների հետ ուտում և խմում»։","17":"Երբ Հիսուսը լսեց, նրանց ասաց. «Առողջներին բժիշկ պետք չէ, այլ հիվանդներին. ես եկել եմ ոչ թե արդարներին, այլ մեղավորներին ապաշխարության կոչելու»։","18":"Հովհաննեսի աշակերտներն ու փարիսեցիները ծոմ էին պահում։ Ոմանք նրա մոտ եկան ու ասացին. «Ինչո՞ւ են Հովհաննեսի ու փարիսեցիների աշակերտները ծոմ պահում, իսկ քո աշակերտները ծոմ չեն պահում»։","19":"Եվ Հիսուսը նրանց ասաց. «Մի՞թե փեսայի բարեկամները ծոմ պիտի պահեն, քանի դեռ նա իրենց հետ է. ինչքան ժամանակ որ փեսան նրանց հետ է, ծոմ չպիտի պահեն։","20":"Բայց օրեր կգան, և փեսան նրանց միջից կվերցվի. այդ օրերին էլ ծոմ կպահեն։","21":"Ոչ ոք հին հագուստի վրա նոր կտորից կարկատան չի գցի, այլապես նոր կարկատանը հին կտորը կքաշի, և պատռվածքն ավելի վատ կլինի։","22":"Եվ ոչ ոք նոր գինին հին տիկերի մեջ չի լցնի, այլապես նոր գինին տիկերը կպայթեցնի, գինին կթափվի, տիկերն էլ կփչանան. այլ նոր գինին նոր տիկերի մեջ պետք է լցվի»։","23":"Եվ այնպես եղավ, որ նա շաբաթ օրն անցնում էր արտերով, ու նրա աշակերտներն սկսեցին հասկ պոկելով գնալ։","24":"Փարիսեցիները նրան ասացին. «Տե՛ս, շաբաթ օրով ի՛նչ են անում. օրինավոր չէ»։","25":"Եվ նա ասաց նրանց. «Դուք երբևէ չե՞ք կարդացել, թե Դավիթն ի՛նչ արեց, երբ կարիքի մեջ էր, երբ սոված էին և՛ ինքը, և՛ իր հետ եղողները.","26":"ինչպե՛ս Աբիաթար քահանայապետի օրոք Աստծու տուն մտավ ու առաջավորության հացերը կերավ և իր հետ եղողներին էլ տվեց։ Այնինչ բացի քահանայից, ոչ ոքի համար օրինավոր չէր ուտելը»։","27":"Եվ Հիսուսը նրանց ասաց. «Շաբաթը մարդու համար է, և ոչ թե մարդը՝ շաբաթի համար։","28":"Հետևաբար Մարդու Որդին շաբաթի՛ էլ տերն է»։"},"3":{"1":"Հիսուսը դարձյալ ժողովարան մտավ։ Այնտեղ ձեռքը չորացած մի մարդ կար։","2":"Եվ սպասում էին Հիսուսին՝ տեսնելու, թե արդյոք շաբաթ օրով կբուժի՞ նրան, որպեսզի ամբաստանեին։","3":"Նա ձեռքը չորացած մարդուն ասաց. «Վե՛ր կաց, մեջտե՛ղ արի»։","4":"Իսկ նրանց հարցրեց. «Օրենքը որևէ մեկին թույլ է տալիս շաբաթ օրը բարի՞ գործ անել, թե՞ չար, մի կյանք փրկե՞լ, թե՞ կորցնել»։ Եվ նրանք լռեցին։","5":"Նա, իր շուրջը եղողներին բարկությամբ նայելով, նրանց սրտերի կուրության համար տրտմած, այն մարդուն ասաց. «Ձեռքդ մեկնի՛ր»։ Նա մեկնեց, ու նրա ձեռքն առողջացավ։","6":"Եվ փարիսեցիներն անմիջապես դուրս գնացին. հերովդեսականների հետ նրա դեմ խորհուրդ էին անում, թե նրան ինչպե՛ս կորցնեն։","7":"Եվ Հիսուսն իր աշակերտների հետ լճի մոտ գնաց։ Եվ Գալիլեայից ու Հուդայից մեծ բազմություններ էին նրա հետևից գնում։","8":"Բազում ժողովուրդ Երուսաղեմից, Եդովմից, Հորդանանից դուրս գտնվող շրջանից, ինչպես նաև նրանք, որ Տյուրոսի ու Սիդովնի շրջակայքից էին, երբ լսում էին, թե ինչե՛ր է անում, նրա մոտ էին գալիս։","9":"Հիսուսն իր աշակերտներին ասաց, որ բազմության պատճառով իր համար մի փոքր նավ պատրաստ պահեն, որպեսզի մարդիկ իրեն չսեղմեն։","10":"Քանի որ շատերին էր բժշկել, արդ ովքեր տառապում էին հիվանդություններից, նրա վրա էին թափվում նրան դիպչելու համար։","11":"Եվ երբ պիղծ ոգիները նրան տեսնում էին, նրա առաջն էին ընկնում, աղաղակում էին ու ասում. «Դու Աստծու Որդին ես»։","12":"Եվ նա խիստ սաստում էր նրանց, որ իր ով լինելը չհայտնեն։","13":"Հիսուսը լեռը բարձրացավ և իր մոտ կանչեց նրանց, ում որ կամեցավ։ Եվ նրանք նրա մոտ գնացին։","14":"Նա ընտրեց տասներկու հոգու, որ իր հետ լինեն, որ նրանց ուղարկի քարոզելու,","15":"և որ նրանք ցավերը բուժելու, դևեր հանելու իշխանություն ունենան։","16":"Նա ընտրեց Սիմոնին, որի անունը Պետրոս դրեց,","17":"Զեբեդեոսի որդի Հակոբոսին ու Հակոբոսի եղբորը՝ Հովհաննեսին, որոնց անվանեց Բաներեգես, որ է «Որոտման որդիներ»,","18":"Անդրեասին, Փիլիպպոսին, Բարթողոմեոսին, Մատթեոսին, Թովմասին, Ալփեոսի որդի Հակոբոսին, Թադեոսին, Սիմոն Կանանացուն","19":"և Հուդա Իսկարիովտացուն, որն էլ մատնեց նրան։","20":"Եվ տուն եկան. դարձյալ բազմություն հավաքվեց, նույնիսկ չկարողացան հաց ուտել։","21":"Նրա յուրայինները, լսելով, դուրս եկան նրան բռնելու, որովհետև կարծում էին, թե խելագարվել է։","22":"Իսկ դպիրները, որ Երուսաղեմից էին եկել, ասում էին, թե Բեեղզեբուղ ունի և դևերի իշխանի ձեռքով է դևերին հանում։","23":"Այդ ժամանակ Հիսուսը, նրանց իր մոտ կանչելով, առակներով ասում էր նրանց. «Սատանան ինչպե՞ս կարող է սատանային դուրս հանել։","24":"Եթե մի թագավորություն իր մեջ բաժանվի, այդ թագավորությունը չի կարող հարատևել։","25":"Եվ եթե մի տուն ինքն իր մեջ բաժանվի, այդ տունը կանգուն մնալ չի կարող։","26":"Եթե սատանան ինքն իր դեմ դուրս գա և բաժանվի, չի կարող կանգուն մնալ. նրա վախճանը հասել է։","27":"Ոչ ոք, զորեղ մարդու տունը մտնելով, չի կարող նրա ունեցվածքը կողոպտել, եթե նախ այդ զորեղ մարդուն չկապի. հետո նրա տունը կկողոպտի։","28":"Ճշմարիտ եմ ասում ձեզ. մարդկանց որդիների բոլոր մեղքերն ու հայհոյանքները կներվեն,","29":"բայց ով Սուրբ Հոգուն հայհոյի, հավիտյան թողություն չի ստանա, այլ հավիտենական դատապարտության կենթարկվի»։","30":"Հիսուսն այս ասաց, որովհետև ասում էին, թե նրա մեջ պիղծ ոգի կա։","31":"Հետո եկան նրա մայրն ու եղբայրները և դրսում կանգնած՝ նրա մոտ մարդ ուղարկեցին, որ նրան կանչի։","32":"Նրա շուրջը նստել էր բազմությունը։ Նրան ասացին. «Ահա մայրդ ու եղբայրներդ դրսում քեզ են ուզում»։","33":"Եվ նա պատասխանեց նրանց ու ասաց. «Ո՞վ է իմ մայրը, կամ ովքե՞ր են իմ եղբայրները»։","34":"Ապա իր շուրջը նստածներին նայեց ու ասաց. «Ահա իմ մայրն ու իմ եղբայրները։","35":"Որովհետև ով կատարում է Աստծու կամքը, նա է իմ եղբայրը, քույրն ու մայրը»։"},"4":{"1":"Հիսուսը դարձյալ սկսեց ուսուցանել լճի մոտ։ Նրա շուրջը մեծ բազմություն հավաքվեց, դրա համար նա նավի մեջ նստեց, իսկ ողջ բազմությունը մնաց ցամաքում՝ լճի մոտ։","2":"Նրանց շատ բաներ էր ուսուցանում առակներով և ասում.","3":"«Լսե՛ք. ահա սերմնացանը դուրս եկավ սերմ ցանելու։","4":"Եվ սերմանելիս մի քանիսը ճանապարհի եզրին ընկան. երկնքի թռչունները եկան ու կերան դրանք։","5":"Մյուսները քարքարոտ տեղ ընկան, որտեղ շատ հող չկար. հողի խոր չլինելու պատճառով արագ բուսնեցին։","6":"Բայց երբ արեգակը ծագեց, տաքացավ, արմատ չունենալու պատճառով չորացան։","7":"Մեկ այլ մասը փշերի մեջ ընկավ. փշերը բարձրացան ու խեղդեցին դրանց, և պտուղ չտվեցին։","8":"Մյուսները պարարտ հողի մեջ ընկան, բուսնելով ու աճելով՝ պտուղ տվեցին. մեկը՝ երեսուն, մեկը՝ վաթսուն, մեկն էլ՝ հարյուր»։","9":"Եվ ասում էր. «Ով լսելու ականջ ունի, թող լսի»։","10":"Երբ Հիսուսը մենակ մնաց, ովքեր նրա հետ էին, ինչպես նաև տասներկու աշակերտները, նրան հարցրին այդ առակի մասին։","11":"Եվ նա ասաց նրանց. «Ձեզ տրված է, որ Աստծու արքայության խորհուրդն իմանաք, սակայն նրանց, որ դրսում են, ամեն բան առակներով է ներկայացվում,","12":"որպեսզի ինչքան էլ նայեն, չտեսնեն, ինչքան էլ լսեն, չիմանան. չլինի թե դարձի գան, ու նրանց մեղքերը ներվեն (Ես. 6.9-10)»։","13":"Եվ նրանց ասաց. «Եթե այս առակը չեք հասկանում, ապա ինչպե՞ս եք հասկանալու մյուս բոլոր առակները։","14":"Սերմնացանը Աստծու խոսքն է սերմանում։","15":"Ճանապարհի եզրին ընկածները նրանք են, որոնց մեջ սերմանվում է խոսքը, բայց երբ լսում են, սատանան իսկույն գալիս է և վերցնում նրանց սրտերի մեջ սերմանված խոսքը։","16":"Այդպես էլ քարքարոտ տեղում սերմանվածները նրանք են, որոնք երբ խոսքը լսում են, ուրախությամբ իսկույն ընդունում են այն։","17":"Բայց իրենց մեջ արմատ չունեն և ժամանակավոր են։ Հետո երբ այդ խոսքի համար նեղություն կամ հալածանք է լինում, իսկույն հրաժարվում են։","18":"Փշերի մեջ սերմանվածները նրանք են, որոնք խոսքը լսում են,","19":"բայց աշխարհիս հոգսերն ու հարստության պատրանքը և ուրիշ ցանկությունները ներխուժում են, խոսքը խեղդում և անպտուղ են դարձնում։","20":"Բայց պարարտ հողի մեջ սերմանվածները նրանք են, որոնք լսում են խոսքը, ընդունում և պտուղ են տալիս. մեկը՝ երեսուն, մեկը՝ վաթսուն, մեկը՝ հարյուր»։","21":"Եվ նրանց ասաց. «Մի՞թե ճրագը բերվում է, որ գրվանի կամ մահճի տակ դրվի. չէ՞ որ ճրագակալի վրա պիտի դրվի։","22":"Այդպես էլ չկա ծածուկ բան, որ հայտնի չդառնա, և չի եղել մի գաղտնիք, որ հայտնի չի դարձել։","23":"Ով լսելու ականջ ունի, թող լսի»։","24":"Եվ նրանց ասաց. «Ուշադի՛ր եղեք, թե ի՛նչ եք լսում. ինչ չափով որ չափեք, նույնով էլ ձեզ համար կչափեն, և ձեզ՝ լսողներիդ, կավելանա։","25":"Որովհետև ով ունի, նրան կտրվի, իսկ ով չունի, նրանից կվերցվի նաև այն, ինչ ունի»։","26":"Եվ Հիսուսն ասում էր. «Աստծու արքայությունն այսպես է. ասես մի մարդ հողի մեջ սերմ ցանի։","27":"Գիշերը քնի ու ցերեկը վեր կենա, իսկ սերմը բուսնի ու աճի, այնպես որ ինքը չիմանա։","28":"Հողն ինքնիրեն պտուղ է տալիս. նախ՝ ծիլ, հետո՝ հասկ, դրանից հետո՝ հասկի մեջ լցված ցորեն։","29":"Բայց երբ պտուղը հասունանա, իսկույն մանգաղ կուղարկի, որովհետև հնձի ժամանակը հասած կլինի»։","30":"Եվ ասում էր. «Աստծու արքայությունն ինչի՞ նմանեցնենք կամ ի՞նչ օրինակով այն ներկայացնենք։","31":"Այն նման է մանանեխի հատիկի, որ երբ հողի մեջ է սերմանվում, աշխարհի վրա եղած բոլոր սերմերից էլ փոքր է։","32":"Բայց երբ սերմանվում է, բուսնում է, բոլոր թփերից ավելի մեծ է լինում և այնքան մեծ ճյուղեր է արձակում, որ երկնքի թռչունները նրա հովանու տակ կարողանում են բույն դնել»։","33":"Եվ այդպես նրանց հետ շատ առակներով էր խոսում, որ նրանք կարողանային լսել։","34":"Նրանց հետ առանց առակի չէր խոսում, բայց իր աշակերտներին առանձին ամեն ինչ բացատրում էր։","35":"Այդ օրը՝ իրիկնադեմին, Հիսուսն աշակերտներին ասաց. «Եկեք մյուս կողմն անցնենք»։","36":"Եվ ժողովրդին թողեցին ու նրան, որ նավի վրա էր, վերցնելով՝ հեռացան։ Նրանց ուրիշ նավակներ էլ էին հետևում։","37":"Ուժեղ փոթորիկ եղավ, և ալիքները նավի մեջ էին թափվում. նավը գրեթե ջրով էր լցվել։","38":"Հիսուսը նավի հետևի մասում բարձի վրա քնած էր։ Նրան արթնացրին ու ասացին. «Վարդապե՛տ, քեզ հոգ չէ՞, որ կորչում ենք»։","39":"Նա, արթնանալով, քամուն սաստեց ու լճին ասաց. «Լռի՛ր, հանդարտվի՛ր»։ Եվ քամին դադարեց, ու կատարյալ խաղաղություն տիրեց։","40":"Եվ նրանց ասաց. «Ինչո՞ւ եք այդքան վախկոտ, ինչո՞ւ հավատ չունեք»։","41":"Նրանք սաստիկ վախեցան ու իրար մեջ ասում էին. «Ո՞վ է արդյոք սա, որ և՛ քամին, և՛ լիճը հնազանդվում են սրան»։"},"5":{"1":"Եկան լճի մյուս կողմը՝ գերգեսացիների երկիրը։","2":"Երբ Հիսուսը նավից դուրս եկավ, գերեզմաններից պիղծ ոգով բռնված մի մարդ նրա դեմը ելավ։","3":"Նա բնակվում էր գերեզմանոցում. նրան ոչ ոք նույնիսկ շղթաներով չէր կարողանում կապել։","4":"Շատ անգամ էին նրան ոտնակապերով ու շղթաներով կապել, բայց նա շղթաները կոտրել էր, ոտնակապերը՝ փշրել։ Ոչ ոք չէր կարողանում նրան զսպել։","5":"Եվ գիշեր ու ցերեկ շարունակ նա գերեզմանոցում և սարերում աղաղակում էր ու ինքն իրեն քարերով ծեծում։","6":"Սակայն երբ հեռվից Հիսուսին տեսավ, վազեց և երկրպագեց նրան","7":"և բարձրաձայն աղաղակելով՝ ասաց. «Ինձ հետ ի՞նչ ունես, Հիսո՛ւս, Բարձրյալ Աստծո՛ւ Որդի։ Աստծով եմ քեզ երդվեցնում, ինձ մի՛ տանջիր».","8":"որովհետև Հիսուսն ասում էր նրան. «Պի՛ղծ ոգի, դո՛ւրս արի այդ մարդու միջից»։","9":"Հիսուսը նրան հարցրեց. «Անունդ ի՞նչ է»։ Նա պատասխանեց ու ասաց. «Իմ անունը Լեգեոն է, որովհետև մենք շատ ենք»։","10":"Եվ դևերը շատ էին աղաչում նրան, որ իրենց այդ տարածքից դուրս չուղարկեր։","11":"Այնտեղ՝ լեռան լանջին, խոզերի մի մեծ երամակ կար, որ արածում էր։","12":"Դևերը նրան աղաչեցին ու ասացին. «Մեզ այն խոզերի մե՛ջ ուղարկիր, որ նրանց մեջ մտնենք»։","13":"Հիսուսն անմիջապես հրամայեց նրանց, և պիղծ ոգիները դուրս եկան, խոզերի մեջ մտան։ Երամակն էլ այն գահավեժ տեղից դեպի լիճը խուժեց։ Եվ խոզերը, որ երկու հազարի չափ էին, լճում խեղդվեցին։","14":"Խոզարածները փախան և այդ մասին քաղաքում ու գյուղերում պատմեցին։ Մարդիկ դուրս եկան տեսնելու, թե ի՛նչ էր պատահել։","15":"Եկան Հիսուսի մոտ և դիվահարին, որ լեգեոն ուներ, նստած, հագնված ու խելքը գլուխը եկած տեսան ու վախեցան։","16":"Տեսնողները նրանց պատմեցին, թե ի՛նչ եղավ այն դիվահարի և խոզերի հետ։","17":"Եվ սկսեցին աղաչել Հիսուսին, որ իրենց սահմաններից դուրս գնա։","18":"Եվ երբ նա նավ էր մտնում, դիվահարը նրան աղաչում էր, որ նրա հետ լինի։","19":"Բայց Հիսուսը նրան թույլ չտվեց, այլ նրան ասաց. «Գնա՛ քո տուն, քո ընտանիքի մոտ ու նրանց պատմի՛ր, թե Տերը քեզ ինչե՛ր արեց ու քեզ ինչպե՛ս ողորմեց»։","20":"Նա գնաց ու սկսեց Դեկապոլիսում քարոզել, ինչ որ Հիսուսն արել էր իրեն։ Եվ բոլորը զարմանում էին։","21":"Երբ Հիսուսը նավով դարձյալ լճի մյուս կողմն անցավ, նրա շուրջը շատ ժողովուրդ հավաքվեց։ Եվ նա լճի ափին էր։","22":"Եվ ահա եկավ ժողովրդապետներից մեկը, անունը՝ Հայրոս։ Երբ Հիսուսին տեսավ, նրա ոտքերի առաջ ընկավ.","23":"նրան շատ էր աղաչում և ասում. «Աղջիկս մահամերձ է։ Արի՛, ձեռքդ վրա՛ն դիր, որպեսզի բժշկվի ու ապրի»։","24":"Եվ Հիսուսը գնաց նրա հետ։ Նրան մեծ բազմություն էր հետևում, որը և նեղում էր նրան։","25":"Մի կին կար, որ տասներկու տարի արյունահոսություն ուներ։","26":"Նա բազում բժիշկների կողմից շատ էր չարչարվել, իր ամբողջ ունեցվածքը վատնել ու ոչ մի օգուտ չէր ստացել, ընդհակառակը, ավելի էր վատացել։","27":"Երբ Հիսուսի մասին լսեց, ամբոխի միջով նրա հետևի կողմը եկավ և նրա հագուստին դիպավ,","28":"որովհետև ասում էր. «Եթե միայն նրա հագուստին դիպչեմ, կբժշկվեմ»։","29":"Նրա արյունահոսությունն անմիջապես դադարեց, և իր մարմնի մեջ զգաց, որ իրեն տանջող հիվանդությունից բժշկվեց։","30":"Հիսուսն էլ միևնույն ժամանակ իր ներսում զգաց, որ իրենից զորություն դուրս եկավ։ Նա դեպի բազմությունը դարձավ ու ասաց. «Իմ հագուստին ո՞վ դիպավ»։","31":"Նրա աշակերտներն ասացին նրան. «Տեսնում ես, որ բազմությունը քեզ նեղում է, և հարցնում ես՝ \"Իմ հագուստին ո՞վ դիպավ\"»։","32":"Բայց նա շուրջն էր նայում, որ այդ բանն անողին տեսնի։","33":"Այդժամ կինը, իմանալով այն, ինչ իրեն պատահեց, վախեցած ու դողալով եկավ, նրա առաջ ընկավ և ամբողջ ճշմարտությունն ասաց նրան։","34":"Հիսուսն ասաց նրան. «Դո՛ւստր, քո հավատը քեզ փրկեց. գնա՛ խաղաղությամբ ու քո հիվանդությունից բժշկվա՛ծ եղիր»։","35":"Նա դեռ խոսում էր, երբ ժողովրդապետի տնից եկան ու ասացին. «Աղջիկդ մեռավ, էլ ինչո՞ւ ես Վարդապետին նեղություն տալիս»։","36":"Հիսուսը հենց այս խոսքերը լսեց, ժողովրդապետին ասաց. «Մի՛ վախենա, այլ միայն հավատա՛»։","37":"Եվ ոչ ոքի թույլ չտվեց, որ իր հետ գնա, բացի Պետրոսից, Հակոբոսից ու Հակոբոսի եղբորից՝ Հովհաննեսից։","38":"Երբ ժողովրդապետի տուն եկավ, այնտեղ իրարանցում և լացուկոծ տեսավ։","39":"Ներս մտավ և նրանց ասաց. «Ինչո՞ւ եք իրար անցել ու լաց լինում։ Երեխան մեռած չէ, այլ քնած է»։","40":"Իսկ նրանք ծիծաղում էին նրա վրա։ Բայց նա բոլորին դուրս արեց և վերցնելով երեխայի հորն ու մորը և իր հետ եկածներին՝ մտավ այնտեղ, որտեղ երեխան էր պառկած։","41":"Հիսուսը, երեխայի ձեռքը բռնելով, նրան ասաց. «Տալի՛թա, կո՛ւմի», որ նշանակում է՝ «Աղջի՛կ, ասո՛ւմ եմ քեզ, վե՛ր կաց»։","42":"Աղջիկն իսկույն վեր կացավ ու ման էր գալիս, որովհետև մոտ տասներկու տարեկան էր։ Բոլորը շատ զարմացան։","43":"Հիսուսը նրանց խստիվ պատվիրեց, որ ոչ ոք դրա մասին չիմանա, և ասաց, որ նրան ուտելու բան տան։"},"6":{"1":"Հիսուսն այնտեղից դուրս եկավ և գնաց իր հայրենի քաղաքը։ Նրա աշակերտները գնում էին նրա հետևից։","2":"Շաբաթ օրը սկսեց ժողովարանում ուսուցանել. շատերը, նրան լսելով, զարմանում էին ու ասում. «Սրան այս բաները որտեղի՞ց, կամ այդ ի՞նչ իմաստություն է սրան տրված, որ սրա միջոցով այդպիսի հրաշքներ են լինում։","3":"Սա այն հյուսնը չէ՞, Մարիամի որդին, Հակոբոսի ու Հովսեսի, Հուդայի ու Սիմոնի եղբայրը։ Սրա քույրերն այստեղ՝ մեզ մոտ չե՞ն»։ Եվ դա խանգարում էր նրանց հավատալ Հիսուսին։","4":"Հիսուսը նրանց ասաց. «Չկա մի մարգարե, որ չանարգվի իր հայրենիքում, իր ազգականների ու իր տան մեջ»։","5":"Եվ չէր կարողանում այնտեղ ոչ մի հրաշք գործել, բացի մի քանի հիվանդների վրա ձեռքերը դնելուց ու բժշկելուց։","6":"Եվ զարմանում էր նրանց անհավատության վրա։ Հիսուսը շրջում էր շրջակա գյուղերում և ուսուցանում։","7":"Եվ իր մոտ կանչեց տասներկուսին ու սկսեց երկու-երկու ուղարկել՝ նրանց իշխանություն տալով պիղծ ոգիների վրա։","8":"Նրանց պատվիրեց, որ ճանապարհի համար ոչինչ չվերցնեն, բացի գավազանից. ո՛չ մախաղ, ո՛չ հաց, ո՛չ էլ դրամ գոտու մեջ,","9":"այլ հողաթափեր հագնեն և երկուական հագուստ չվերցնեն։","10":"Նրանց նաև ասաց. «Ո՛ր տունը մտնեք, այնտե՛ղ մնացեք այնքան ժամանակ, մինչև այնտեղից մեկնեք։","11":"Եվ ովքեր ձեզ չընդունեն ու ձեզ ականջ չդնեն, այնտեղից դուրս գալիս ձեր ոտքերից փոշին թա՛փ տվեք՝ որպես վկայություն նրանց դեմ։ Ճշմարիտ եմ ասում ձեզ. Սոդոմի ու Գոմորի դատաստանի օրն ավելի հեշտ կլինի, քան այն քաղաքինը»։","12":"Աշակերտները դուրս ելան և քարոզում էին, որ մարդիկ ապաշխարեն։","13":"Շատ դևեր էին հանում, շատ հիվանդների յուղով օծում էին և բժշկում նրանց։","14":"Եվ Հերովդես թագավորը լսեց Հիսուսի մասին, որովհետև նրա անունը հայտնի էր դարձել։ Ոմանք ասում էին, թե Հովհաննես Մկրտիչը մեռելներից հարություն է առել, և դրա համար նրա կողմից հրաշքներ են գործվում։","15":"Ոմանք ասում էին, թե Եղիան է, ոմանք էլ, թե մարգարե է կամ մարգարեների նման մեկը։","16":"Եվ երբ Հերովդեսը լսեց, ասաց. «Սա Հովհաննեսն է, որին ես գլխատեցի. նա մեռելներից հարություն է առել»։","17":"Որովհետև Հերովդեսն ինքն էր ուղարկել Հովհաննեսին բռնելու և նրան բանտարկելու իր եղբոր՝ Փիլիպպոսի կնոջ՝ Հերովդիայի պատճառով, որին կնության էր առել։","18":"Իսկ Հովհաննեսը Հերովդեսին ասել էր. «Չի թույլատրվում, որ եղբորդ կնոջն առնես»։","19":"Հերովդիան նրա դեմ ոխ էր պահում և ուզում էր սպանել նրան, բայց չէր կարողանում,","20":"որովհետև Հերովդեսը Հովհաննեսից վախենում էր։ Նա գիտեր, որ Հովհաննեսը արդար ու սուրբ մարդ է, և խնայում էր նրան՝ նրա ասածներից շատ բաներ անելով, և հաճույքով լսում էր նրան։","21":"Մի հարմար օր պատահեց, երբ Հերովդեսն իր ծննդյան օրն ընթրիքի էր հրավիրել նախարարներին, զորապետներին ու Գալիլեայի մեծամեծներին։","22":"Երբ Հերովդիայի աղջիկը ներս մտավ և պարեց, Հերովդեսին ու հրավիրվածներին դուր եկավ։ Թագավորն աղջկան ասաց. «Խնդրի՛ր ինձանից, ինչ ուզում ես, և ես կտամ քեզ»։","23":"Եվ նրան երդվեց. «Ի՛նչ էլ ինձանից խնդրես, կտամ քեզ, մինչև իսկ իմ թագավորության կեսը»։","24":"Նա դուրս գնաց, իր մորը հարցրեց. «Ի՞նչ խնդրեմ»։ Իսկ նա պատասխանեց. «Հովհաննես Մկրտչի գլուխը»։","25":"Աղջիկը շտապ թագավորի մոտ մտավ ու ասաց. «Ուզում եմ, որ հիմա Հովհաննես Մկրտչի գլուխը սկուտեղի վրա ինձ տաս»։","26":"Թագավորը շատ տրտմեց, բայց հրավիրվածների ներկայությամբ տված երդման պատճառով չցանկացավ նրան մերժել։","27":"Թագավորն իսկույն դահիճ ուղարկեց և հրամայեց Հովհաննեսի գլուխը բերել։ Եվ նա գնաց ու բանտում գլխատեց նրան։","28":"Նա գլուխն սկուտեղի վրա բերեց և տվեց աղջկան, իսկ աղջիկը մորը տվեց այն։","29":"Երբ Հովհաննեսի աշակերտները լսեցին, եկան վերցրին նրա մարմինն ու գերեզման դրեցին։","30":"Առաքյալները Հիսուսի մոտ վերադարձան և նրան պատմեցին այն ամենը, ինչ արել էին և ինչ որ ուսուցանել էին։","31":"Հիսուսն ասաց նրանց. «Դուք առանձին մի ամայի տե՛ղ եկեք ու մի քիչ հանգստացե՛ք»։ Որովհետև եկող-գնացողները շատ էին, և նույնիսկ հաց ուտելու ժամանակ չունեին։","32":"Եվ նավով մի ամայի տեղում առանձնացան։","33":"Շատերը նրանց գնալիս տեսան և ճանաչեցին։ Բոլոր քաղաքներից ոտքով այնտեղ էին վազում։ Նրանք նրանցից շուտ այնտեղ հասան ու հավաքվեցին Հիսուսի շուրջը։","34":"Երբ Հիսուսը ցամաք ելավ, մեծ բազմություն տեսավ. գթաց նրանց, որովհետև հովիվ չունեցող ոչխարների էին նման։ Եվ սկսեց նրանց շատ բաներ ուսուցանել։","35":"Երբ արդեն շատ ժամանակ էր անցել, աշակերտները մոտեցան նրան և ասացին. «Այս վայրն ամայի է, և ուշ ժամ է։","36":"Ժողովրդին արձակի՛ր, որ շրջակա ագարակներն ու գյուղերը գնան հաց առնելու, որովհետև այստեղ ուտելու բան չունեն»։","37":"Նա պատասխանեց նրանց ու ասաց. «Դո՛ւք դրանց ուտելիք տվեք»։ Այդժամ նրան ասացին. «Գնանք երկու հարյուր դինարի հաց առնենք ու նրանց տանք, որ ուտե՞ն»։","38":"Իսկ նա հարցրեց նրանց. «Քանի՞ հատ հաց ունեք։ Գնացե՛ք ու տեսե՛ք»։ Երբ իմացան, նրան ասացին. «Հինգ հաց և երկու ձուկ»։","39":"Այդ ժամանակ նրանց կարգադրեց, որ բոլորին խումբ-խումբ նստեցնեն դալար խոտի վրա։","40":"Եվ նրանք դաս-դաս նստեցին՝ հարյուր-հարյուր և հիսուն-հիսուն։","41":"Հիսուսը վերցրեց հինգ հացն ու երկու ձուկը, դեպի երկինք նայեց, դրանք օրհնեց, հացերը մասերի բաժանեց ու աշակերտներին տվեց, որ նրանց բաժանեն։ Այն երկու ձկները նույնպես բոլորին բաժանեց։","42":"Բոլորն էլ կերան ու կշտացան։","43":"Հացի ու ձկան կտորներից հավաքեցին նաև տասներկու լիքը կողով։","44":"Նրանք, որ հաց կերան, մոտ հինգ հազար տղամարդ էին։","45":"Ապա անմիջապես իր աշակերտներին ստիպեց, որ նավ մտնեն, գնան դիմացի ափը՝ Բեթսայիդա, և այնտեղ իրեն սպասեն, մինչև որ ինքը ժողովրդին արձակի։","46":"Եվ նրանց հրաժեշտ տալով՝ բարձրացավ լեռը՝ աղոթելու։","47":"Երբ երեկո եղավ, նավը լճի մեջտեղում էր, իսկ Հիսուսը՝ ցամաքին, մենակ։","48":"Եվ տեսավ, որ թիավարելիս նրանք չարչարվում էին, որովհետև քամին նրանց հակառակ էր փչում։ Գիշերվա չորրորդ ժամին Հիսուսը, լճի վրա քայլելով, նրանց մոտ եկավ և ուզում էր նրանցից առաջ անցնել։","49":"Երբ աշակերտները տեսան նրան լճի վրա քայլելիս, կարծեցին, թե ուրվական է, և աղաղակեցին։","50":"Որովհետև բոլորը նրան տեսան ու վախեցան։ Եվ Հիսուսն իսկույն նրանց հետ խոսեց ու ասաց. «Քաջալերվե՛ք, ես եմ, մի՛ վախեցեք»։","51":"Ապա նրանց մոտ՝ նավ բարձրացավ, ու քամին դադարեց։ Եվ աշակերտները չափազանց ապշած ու զարմացած էին։","52":"Որովհետև չէին հասկացել նաև այն հացի հրաշքը, քանի որ նրանց սիրտն ընդարմացած էր։","53":"Եվ լճի մյուս կողմն անցնելով՝ եկան Գեննեսարեթ ու ցամաք ելան։","54":"Երբ նրանք դուրս եկան նավից, մարդիկ իսկույն ճանաչեցին Հիսուսին։","55":"Այդժամ գավառի ամբողջ շրջակայքից վազեցին և սկսեցին մահիճներով հիվանդների բերել, որտեղ լսում էին, թե Հիսուսն այնտեղ է։","56":"Եվ ուր որ մտնում էր՝ գյուղեր, քաղաքներ թե ագարակներ, հիվանդներին հրապարակներում էին դնում ու նրան խնդրում էին, որ գոնե հագուստի քղանցքին դիպչեին։ Եվ ովքեր որ նրան դիպան, բժշկվեցին։"},"7":{"1":"Փարիսեցիներն ու դպիրներից ոմանք, որ Երուսաղեմից էին եկել, նրա շուրջը հավաքվեցին։","2":"Եվ երբ տեսան, որ նրա աշակերտներից մի քանիսը անմաքուր ձեռքերով, այսինքն՝ առանց լվացվելու, հաց են ուտում, հանդիմանեցին նրանց։","3":"Որովհետև փարիսեցիներն ու բոլոր հրեաները, եթե նախօրոք ձեռքերը չեն լվանում, չեն ուտում՝ այդ կերպ պահպանելով նախնիների ավանդույթը։","4":"Ինչպես նաև շուկայից վերադառնալուց հետո չեն ուտում, մինչև նախ չլվացվեն։ Շատ այլ ավանդույթներ էլ են պահպանել, ինչպես բաժակների, անոթների, պղնձե ամանների ու անկողինների լվացումը։","5":"Արդ, փարիսեցիներն ու դպիրները հարցրին Հիսուսին. «Ինչո՞ւ քո աշակերտները նախնիների ավանդույթով չեն առաջնորդվում, այլ անլվա ձեռքերով են հաց ուտում»։","6":"Նա պատասխանեց նրանց ու ասաց. «Եսային լավ է մարգարեացել ձեր՝ կեղծավորներիդ մասին՝ ասելով. \"Այս ժողովուրդն ինձ շրթունքներով է պատվում, իսկ նրա սիրտն ինձանից շատ հեռու է։","7":"Զուր են պաշտում ինձ, քանի որ ուսուցանում են պատվիրաններ, որոնք մարդիկ են հորինել\" (Ես. 29.13)։","8":"Աստծու պատվիրանները թողած՝ մարդկանց ավանդույթներն եք պահում։ Անոթների ու ամանների լվանալը և սրա նման ուրիշ շատ այլ բաներ եք անում»։","9":"Եվ նրանց ասաց. «Շա՜տ լավ. ուրեմն Աստծու պատվիրանը անարգում եք, որ ձեր ավանդույթը պահպանեք։","10":"Որովհետև Մովսեսն ասել է՝ \"Պատվի՛ր հորդ ու մորդ\" (Ելք 20.12, Բ Օր. 5.16) և \"Ով իր հորը և մորը չարախոսի, թող մահով պատժվի\" (Ելք 21.17, Ղևտ. 20.9)։","11":"Բայց դուք ասում եք. \"Եթե մեկը հորը կամ մորն ասի՝ Կորբան, (որ նշանակում է \"Այն օգնությունը, որ ինձանից ստանալու էիր, Աստծուն է տրված\"),","12":"և նրան իր հոր կամ մոր համար որևէ բան անելու պարտականությունից ազատում եք\"։","13":"Եվ Աստծու խոսքը անարգում եք ձեր ավանդույթով, որ ժառանգել եք։ Ու սրա նման ուրիշ շատ բաներ էլ եք անում»։","14":"Եվ ամբողջ ժողովրդին դարձյալ իր մոտ կանչելով՝ ասաց. «Բոլորդ ի՛նձ լսեք ու հասկացե՛ք.","15":"դրսից մարդու մեջ մտնող ոչ մի բան չի կարող նրան պղծել, այլ նրանից դուրս եկող բաներն են, որ պղծում են մարդուն։","16":"Ով լսելու ականջ ունի, թող լսի»։","17":"Երբ Հիսուսը ժողովրդից հեռացավ ու տուն մտավ, նրա աշակերտներն այն առակի մասին հարցրին նրան։","18":"Եվ նա ասաց նրանց. «Դուք է՞լ այդքան անմիտ եք, չգիտե՞ք, որ այն ամենը, ինչ դրսից է մարդու մեջ մտնում, չի կարող նրան պղծել,","19":"որովհետև նրա սրտի մեջ չի մտնում, այլ որովայնի, և դուրս է գնում արտաքնոց՝ ամբողջ կերածը մաքրելով»։","20":"Նա նաև ասաց. «Այն, ինչ դուրս է գալիս մարդու միջից, դա է պղծում մարդուն։","21":"Որովհետև մարդկանց սրտի միջից դուրս են գալիս չար մտքեր, պոռնկություն, գողություններ, սպանություններ,","22":"շնություններ, ագահություն, չարություններ, նենգություն, գիջություն, նախանձ, հայհոյություն, ամբարտավանություն, անզգամություն։","23":"Այս բոլոր չարիքները ներսից են դուրս գալիս ու պղծում մարդուն»։","24":"Հիսուսն այնտեղից ելավ ու գնաց Տյուրոսի և Սիդովնի սահմանները։ Նա մի տուն մտավ և չէր ուզում, որ որևէ մեկն այդ մասին իմանար, բայց չկարողացավ թաքնված մնալ։","25":"Նրա մասին անմիջապես լսեց մի կին, որի աղջիկը պիղծ ոգով էր բռնված։ Նա եկավ և Հիսուսի ոտքերն ընկավ։","26":"Այդ կինը հեթանոս էր, ազգությամբ Փյունիկեի ասորի։ Աղաչում էր նրան, որ իր աղջկա միջից դևին դուրս հանի։","27":"Սակայն Հիսուսը նրան ասաց. «Նախ թող երեխաները կշտանան, որովհետև լավ չէ երեխաների հացն առնել ու շներին գցել»։","28":"Իսկ կինը պատասխանեց ու ասաց նրան. «Այո՛, Տե՛ր, որովհետև շներն էլ երեխաների՝ սեղանից թափած փշրանքներով են կերակրվում»։","29":"Եվ Հիսուսը նրան ասաց. «Այդ խոսքիդ համար գնա՛, դևը քո աղջկա միջից դուրս ելավ»։","30":"Եվ երբ իր տուն վերադարձավ, աղջկան գտավ մահճակալի վրա պառկած և դևին՝ դուրս ելած։","31":"Եվ դարձյալ Տյուրոսի ու Սիդովնի սահմաններից դուրս ելավ և Դեկապոլիսի սահմանների միջով Գալիլեայի լիճ գնաց։","32":"Նրա մոտ մի խուլ ու համր մարդու բերեցին և աղաչում էին, որ ձեռքը նրա վրա դնի։","33":"Հիսուսը նրան ժողովրդից հեռու՝ մի առանձին տեղ տարավ, իր մատները նրա ականջների մեջ դրեց և, թքելով, դիպավ նրա լեզվին։","34":"Հիսուսը դեպի երկինք նայեց, հառաչեց ու նրան ասաց. «Եփփա՛թա», որ նշանակում է «Բացվի՛ր»։","35":"Եվ նրա ականջներն իսկույն բացվեցին, լեզվի կապն արձակվեց, և վարժ խոսում էր։","36":"Հիսուսը նրանց պատվիրեց, որ ոչ ոքի չասեն. սակայն ինչքան էլ նա պատվիրում էր նրանց, այնքան նրանք ավելի էին տարածում։","37":"Չափազանց զարմանում էին ու ասում. «Սա ամեն բան լավ է անում. խուլերին լսել է տալիս, համրերին՝ խոսել»։"},"8":{"1":"Այն օրերին, երբ դարձյալ շատ ժողովուրդ էր հավաքվել, և ուտելու բան չունեին, Հիսուսն իր աշակերտներին կանչեց ու նրանց ասաց.","2":"«Այս ժողովրդին խղճում եմ, որովհետև արդեն երեք օր է՝ ինձ մոտ են և ուտելու ոչինչ չունեն։","3":"Եթե նրանց քաղցած արձակեմ իրենց տները, ճանապարհին կնվաղեն, քանի որ ոմանք հեռվից են եկել»։","4":"Աշակերտները պատասխանեցին նրան. «Ինչպե՞ս կարելի է այս ամայի վայրում նրանց հացով կշտացնել»։","5":"Հիսուսը հարցրեց նրանց. «Քանի՞ հաց ունեք»։ Նրանք պատասխանեցին՝ յոթ։","6":"Հիսուսը ժողովրդին հրամայեց, որ գետնին նստեն։ Եվ վերցրեց այն յոթ հացը, գոհություն հայտնեց, մասերի բաժանեց և իր աշակերտներին տվեց, որ բաժանեն. նրանք էլ բաժանեցին ժողովրդին։","7":"Ունեին նաև մի քանի փոքր ձկներ. նա օրհնեց ու ասաց, որ դրանք էլ բաժանեն։","8":"Կերան ու կշտացան. և յոթ զամբյուղ էլ ավելացած կտորներ հավաքեցին։","9":"Մոտ չորս հազար մարդ կար։ Ապա Հիսուսը նրանց արձակեց","10":"և աշակերտների հետ իսկույն նավ մտավ ու Դաղմանութայի կողմերը եկավ։","11":"Փարիսեցիները եկան ու սկսեցին նրա հետ վիճել. նրան փորձելու համար նրանից նշան էին ուզում երկնքից։","12":"Եվ նա հոգով տրտմեց ու ասաց. «Ինչո՞ւ է այս ազգը նշան ուզում։ Ճշմարիտ եմ ասում ձեզ, որ այս ազգին այդպիսի նշան չի տրվելու»։","13":"Նրանց թողեց, դարձյալ նավ մտավ ու մյուս կողմը գնաց։","14":"Աշակերտները մոռացել էին հաց վերցնել։ Նավում իրենց հետ մեկ հացից բացի ուրիշ ոչինչ չունեին։","15":"Հիսուսը պատվիրեց նրանց ու ասաց. «Զգուշացե՛ք փարիսեցիների ու հերովդեսականների խմորից»։","16":"Աշակերտները մտածում էին և իրար մեջ ասում. «Քանի որ հաց չունենք, դրա համար է այդ ասում»։","17":"Հիսուսը հասկացավ և նրանց ասաց. «Ինչո՞ւ եք մտածում, թե հաց չունեք։ Դեռ չե՞ք հասկանում և չե՞ք հիշում. ձեր սիրտն այդքան ընդարմացա՞ծ է։","18":"Աչք ունեք և չե՞ք տեսնում, ականջ ունեք և չե՞ք լսում ու չե՞ք հիշում։","19":"Երբ այն հինգ հացը հինգ հազար մարդու համար կտրեցի, դրանց կտորներից քանի՞ կողով լիքը վերցրիք»։ Նրան ասացին. «Տասներկու»։","20":"«Իսկ երբ յոթ հացը չորս հազար մարդու համար կտրեցի, դրանց կտորների՞ց քանի զամբյուղ լիքը վերցրիք»։ Նրանք ասացին. «Յոթ»։","21":"Նրանց ասաց. «Հապա ինչպե՞ս չեք հասկանում»։","22":"Եկան Բեթսայիդա. նրա առաջ բերեցին մի կույրի ու խնդրում էին, որ դիպչի նրան։","23":"Հիսուսը կույրի ձեռքից բռնեց, գյուղից դուրս տարավ։ Նրա աչքերին թքելով ու ձեռքով դրանց դիպչելով՝ նրան հարցրեց, թե որևէ բան տեսնո՞ւմ է։","24":"Նա նայեց ու ասաց. «Տեսնում եմ մարդկանց, որոնք քայլող ծառերի նման են»։","25":"Հետո դարձյալ ձեռքերը նրա աչքերի վրա դրեց և նրան հստակ տեսնել տվեց։ Նրա տեսողությունը վերականգնվեց, և բոլորին պարզ տեսնում էր։","26":"Հիսուսը նրան տուն ուղարկեց՝ ասելով. «Ո՛չ գյուղ կմտնես, ո՛չ էլ գյուղում մեկին կասես»։","27":"Հիսուսն իր աշակերտների հետ Փիլիպպյան Կեսարիայի գյուղերը գնաց։ Ճանապարհին աշակերտներին հարցրեց ու ասաց. «Մարդիկ իմ մասին ի՞նչ են ասում. ո՞վ եմ ես»։","28":"Նրանք պատասխանեցին. «Հովհաննես Մկրտիչը, ոմանք՝ Եղիան, ոմանք էլ՝ մարգարեներից մեկը»։","29":"Իսկ նա հարցրեց նրանց. «Հապա դո՞ւք իմ մասին ինչ եք ասում. ո՞վ եմ»։ Պետրոսը պատասխանեց ու նրան ասաց. «Դու Քրիստոսն ես»։","30":"Այդժամ Հիսուսը խստիվ պատվիրեց նրանց, որ այդ մասին ոչ ոքի չասեն։","31":"Հիսուսը սկսեց նրանց ուսուցանել, որ Մարդու Որդին պետք է շատ չարչարվի, փորձության ենթարկվի ծերերից, քահանայապետներից ու դպիրներից, պետք է մահանա և երեք օր հետո հարություն առնի։","32":"Եվ նա բացահայտ խոսում էր նրանց հետ այդ մասին։ Պետրոսը նրան մի կողմ տարավ ու սկսեց հանդիմանել։","33":"Սակայն Հիսուսը դարձավ դեպի իր աշակերտները, նայեց նրանց և Պետրոսին հանդիմանեց ու ասաց. «Հետև՛ս գնա, սատանա՛, որովհետև դու չես մտածում, ինչպես Աստված է կամենում, այլ ինչպես մարդիկ»։","34":"Ապա Հիսուսը ժողովրդին աշակերտների հետ միասին իր մոտ կանչեց ու նրանց ասաց. «Ով ուզում է իմ հետևից գալ, թող իր անձն ուրանա, իր խաչը վերցնի ու իմ հետևից գա։","35":"Որովհետև ով ցանկանա իր կյանքը փրկել, կկորցնի այն, իսկ ով իր կյանքը ինձ համար ու Ավետարանի համար կորցնի, նա կփրկի այն։","36":"Ի՞նչ օգուտ է մարդուն, եթե այս ամբողջ աշխարհը շահի, բայց իր կյանքը կորցնի.","37":"որովհետև մարդն իր կյանքի համար ի՞նչ հատուցում կտա։","38":"Ով, ապրելով այս շնացող և մեղավոր ազգի մեջ, ինձ ու իմ խոսքերը ամոթ համարի, Մարդու Որդին էլ նրա՛ն կամաչեցնի, երբ գա իր Հոր փառքով ու սուրբ հրեշտակներով»։"},"9":{"1":"Եվ նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ այստեղ գտնվողներից ոմանք մահ չեն ճաշակելու, մինչև չտեսնեն Աստծու արքայությունը՝ զորությամբ եկած»։","2":"Վեց օր հետո Հիսուսը իր հետ վերցրեց Պետրոսին, Հակոբոսին ու Հովհաննեսին և նրանց առանձին մի բարձր լեռ հանեց ու նրանց առաջ այլակերպվեց։","3":"Նրա հագուստները դարձան փայլուն, ձյան պես խիստ սպիտակ, այնպես, որ երկրի վրա ոչ մի ներկարար այդպես չէր կարող սպիտակեցնել։","4":"Ապա նրանց երևաց Եղիան՝ Մովսեսի հետ, և խոսում էին Հիսուսի հետ։","5":"Եվ Պետրոսը Հիսուսին ասաց. «Ռա՛բբի, լավ է, որ մենք այստեղ մնանք և երեք տաղավար շինենք. մեկը՝ քեզ համար, մեկը՝ Մովսեսի, մեկն էլ՝ Եղիայի»։","6":"Որովհետև չգիտեր, թե ի՛նչ խոսեր, քանի որ սարսափած էին։","7":"Եվ մի ամպ նրանց վրա հովանի եղավ. այդ ամպից ձայն հնչեց և ասաց. «Դա՛ է իմ սիրելի Որդին, նրա՛ն լսեք»։","8":"Եվ հանկարծ իրենց շուրջը նայեցին, իրենց հետ ոչ ոքի չտեսան, բացի Հիսուսից։","9":"Լեռից իջնելիս նրանց պատվիրեց, որ իրենց տեսածի մասին ոչ մեկի չպատմեն մինչև այն ժամանակը, երբ Մարդու Որդին մեռելներից հարություն առնի։","10":"Նրանք այդ խոսքն իրենց մեջ պահեցին ու իրար հարցնում էին, թե ինչ է նշանակում՝ մեռելներից հարություն կառնի։","11":"Ապա նրան հարցրին. «Ինչո՞ւ են դպիրներն ասում, թե՝ \"Նախ Եղիան պետք է գա\"»։","12":"Հիսուսը պատասխանեց. «Նախ Եղիան կգա և ամեն ինչ կարգի կդնի։ Սակայն ինչո՞ւ է Մարդու Որդու մասին գրված, թե շատ կչարչարվի և կանարգվի։","13":"Բայց ձեզ ասում եմ, որ Եղիան եկավ, և նրանք ինչ որ ուզեցին, արեցին նրան, ինչպես որ նրա մասին գրված է»։","14":"Եվ երբ մնացած աշակերտների մոտ եկավ, տեսավ նրանց շուրջը հավաքված մեծ բազմություն և դպիրներին, որ վիճում էին նրանց հետ։","15":"Իսկույն ամբողջ ժողովուրդը, նրան տեսնելով, անակնկալի եկավ ու ընդառաջ վազեց նրան ողջունելու։","16":"Հիսուսը դպիրներին հարցրեց. «Ինչի՞ մասին եք վիճում նրանց հետ»։","17":"Ժողովրդի միջից մեկը պատասխանեց ու ասաց. «Վարդապե՛տ, քեզ մոտ եմ բերել իմ որդուն, որն իր մեջ պիղծ ոգի ունի և համրացել է։","18":"Որտեղ այն նրան բռնում է, գետնով է տալիս, և նրա բերանից փրփուր է դուրս գալիս, ատամներն է կրճտացնում և փայտանում է։ Քո աշակերտներին ասացի, որ հանեն դրան, բայց չկարողացան»։","19":"Նա պատասխանեց ու ասաց նրանց. «Ո՛վ անհավատ սերունդ, մինչև ե՞րբ եմ ձեզ հետ լինելու, մինչև ե՞րբ եմ ձեզ հանդուրժելու։ Նրան ինձ մո՛տ բերեք»։","20":"Եվ նրան իր մոտ բերեցին։ Հենց որ ոգին Հիսուսին տեսավ, անմիջապես ցնցեց տղային, և նա ընկավ գետնին, թավալվում էր, ու բերանից փրփուր էր դուրս գալիս։","21":"Հիսուսը նրա հորը հարցրեց. «Որքա՞ն ժամանակ է նրան այս պատահել»։ Նա ասաց. «Մանկությունից.","22":"շատ անգամ նրան նաև կրակի ու ջրի մեջ է գցել, որ կորստյան մատնի։ Բայց եթե կարող ես մի բան անել, գթա՛ մեզ և օգնի՛ր»։","23":"Հիսուսը նրան ասաց. «Եթե կարող ես հավատալ. հավատացողի համար ամեն ինչ հնարավոր է»։","24":"Այդժամ տղայի հայրն աղաղակեց ու արտասուքով ասաց. «Հավատում եմ, Տե՛ր, օգնի՛ր իմ անհավատությանը»։","25":"Երբ Հիսուսը տեսավ, որ բազմություն է կուտակվում, սաստեց պիղծ ոգուն ու նրան ասաց. «Համր ու խո՛ւլ ոգի, ես քեզ հրամայում եմ, դո՛ւրս արի նրա միջից ու այլևս չմտնե՛ս նրա մեջ»։","26":"Եվ ոգին, աղաղակելով ու տղային սաստիկ ցնցելով, դուրս ելավ։ Եվ տղան մեռելի պես եղավ, այնպես որ շատերն ասում էին, թե մեռավ։","27":"Հիսուսը բռնեց նրա ձեռքից, բարձրացրեց նրան, և նա ոտքի կանգնեց։","28":"Եվ երբ նա տուն մտավ, աշակերտները նրան առանձին հարցրին. «Մենք ինչո՞ւ չկարողացանք հանել նրան»։","29":"Եվ նա ասաց նրանց. «Այդ դիվային սերնդին ոչ ոք այլ կերպ չի կարող դուրս հանել, եթե ոչ աղոթքով ու ծոմով»։","30":"Նրանք այնտեղից դուրս եկան և անցնում էին Գալիլեայի միջով։ Հիսուսը չէր ուզում, որ որևէ մեկն իմանա,","31":"որովհետև աշակերտներին ուսուցանում էր ու ասում, թե Մարդու Որդին մարդկանց ձեռքն է մատնվելու, և նրանք պիտի սպանեն նրան, բայց երբ սպանվի, երրորդ օրը հարություն է առնելու։","32":"Իսկ նրանք այդ խոսքը չէին հասկանում ու վախենում էին նրան հարցնել։","33":"Հիսուսը Կափառնաում եկավ և երբ տուն մտավ, նրանց հարցրեց. «Ճանապարհին իրար հետ ինչի՞ մասին էիք վիճում»։","34":"Սակայն նրանք լռում էին, որովհետև ճանապարհին իրար հետ վիճում էին, թե ո՛վ է մեծը։","35":"Հիսուսը նստեց, կանչեց տասներկուսին և նրանց ասաց. «Եթե մեկն ուզում է լինել առաջինը, թող լինի բոլորից վերջինը ու բոլորի սպասավորը»։","36":"Ապա վերցրեց մի երեխայի, նրանց մեջտեղում կանգնեցրեց և նրան գրկելով՝ ասաց նրանց.","37":"«Ով այսպիսի երեխաներից մեկին ընդունում է իմ անունով, ի՛նձ է ընդունում, իսկ ով ինձ է ընդունում, ընդունում է ինձ ուղարկողին, այլ ոչ ինձ»։","38":"Հովհաննեսը նրան ասաց. «Վարդապե՛տ, տեսանք մեկին, որ քո անունով դևեր էր հանում, բայց նրան արգելեցինք, որովհետև մեզ չի հետևում»։","39":"Հիսուսն ասաց. «Մի՛ արգելեք նրան, որովհետև չկա մեկը, որ իմ անունով մի հրաշք գործի ու հետո անմիջապես կարողանա ինձ չարախոսել.","40":"որովհետև ով մեզ հակառակ չէ, մեր կողմն է։","41":"Ով հանուն ինձ ձեզ մի բաժակ ջուր տա, քանի որ դուք Քրիստոսին եք պատկանում, ճշմարիտ եմ ասում ձեզ, նա իր վարձը չի կորցնի։","42":"Իսկ ով որ գայթակղեցնի այս փոքրերից մեկին, որ հավատում են ինձ, նրա համար ավելի լավ կլինի, եթե վզից մի աղացքար կախվի, ու նա ծովը գցվի։","43":"Եթե քո ձեռքը գայթակղեցնում է քեզ, կտրի՛ր այն, որովհետև քեզ համար ավելի լավ է, որ հավիտենական կյանք խեղանդամ մտնես, քան երկու ձեռք ունենաս, բայց գեհեն գնաս՝ այն անշեջ կրակի մեջ.","44":"\"Այնտեղ նրանց ուտող որդը չի մեռնում, ու կրակը չի հանգչում\"։","45":"Եվ եթե քո ոտքը գայթակղեցնում է քեզ, կտրի՛ր այն. քեզ համար ավելի լավ է, որ հավիտենական կյանք կաղ մտնես, քան երկու ոտք ունենաս և գեհեն ընկնես՝ այն անշեջ կրակի մեջ.","46":"\"Այնտեղ նրանց ուտող որդը չի մեռնում, ու կրակը չի հանգչում\"։","47":"Եվ եթե քո աչքը գայթակղեցնում է քեզ, հանի՛ր այն. քեզ համար ավելի լավ է, որ մեկ աչքով Աստծու արքայություն մտնես, քան երկու աչք ունենաս ու կրակի գեհենն ընկնես.","48":"\"Այնտեղ նրանց ուտող որդը չի մեռնում, ու կրակը չի հանգչում\"։","49":"Որովհետև ամեն ոք կրակով է աղվելու, ինչպես ամեն զոհ աղով է աղվում։","50":"Աղը լավ բան է, իսկ եթե աղն իր աղիությունը կորցնի, ինչպե՞ս այն կվերագտնեք։ Ձեր անձի մեջ ա՛ղ ունեցեք ու իրար հետ խաղաղության մե՛ջ եղեք»։"},"10":{"1":"Հիսուսն այնտեղից ելավ, եկավ Հրեաստանի սահմանները՝ Հորդանանի մյուս կողմը։ Նրա շուրջը դարձյալ ժողովուրդ էր հավաքվում, և նա իր սովորության համաձայն նորից ուսուցանում էր նրանց։","2":"Նրան մոտեցան նաև փարիսեցիները և փորձելու համար նրան հարցրին. «Թույլատրվո՞ւմ է մարդուն իր կնոջն արձակել»։","3":"Հիսուսը պատասխանեց նրանց ու ասաց. «Մովսեսը ձեզ ի՞նչ է պատվիրել»։","4":"Նրանք ասացին. «Մովսեսը թույլ է տվել բաժանման թուղթ գրել ու արձակել»։","5":"Բայց Հիսուսը պատասխանեց նրանց ու ասաց. «Նա ձեր խստասրտության պատճառով է այդ պատվիրանը ձեզ գրել։","6":"Բայց արարչագործության սկզբից Աստված նրանց արու և էգ ստեղծեց ու ասաց.","7":"\"Դրա համար տղամարդն իր հորն ու մորը կթողնի և իր կնոջը կմիանա։","8":"Եվ երկուսը մեկ մարմին կլինեն\". հետևաբար այլևս երկու չեն, այլ մեկ մարմին։","9":"Արդ, ինչ որ Աստված միավորեց, մարդը թող չբաժանի»։","10":"Տանը աշակերտները այդ թեմայի շուրջ դարձյալ հարցրին նրան։","11":"Եվ նա ասաց նրանց. «Ով իր կնոջն արձակի ու մի ուրիշի հետ ամուսնանա, առաջին կնոջ դեմ շնություն է անում։","12":"Իսկ եթե մի կին իր ամուսնուն արձակի և ուրիշ տղամարդու հետ ամուսնանա, շնություն է անում»։","13":"Հիսուսի մոտ երեխաների էին բերում, որ օրհնի նրանց, բայց աշակերտները սաստում էին բերողներին։","14":"Բայց երբ Հիսուսը տեսավ, բարկացավ ու նրանց ասաց. «Թողե՛ք, որ երեխաներն ինձ մոտ գան, ու մի՛ արգելեք նրանց, քանի որ Աստծու արքայությունն այդպիսիներինն է։","15":"Ճշմարիտ եմ ասում ձեզ. ով Աստծու արքայությունը երեխայի պես չընդունի, նրա մեջ չի մտնի»։","16":"Եվ նրանց գիրկն առավ, ձեռքը նրանց վրա դրեց և օրհնեց։","17":"Հիսուսը պատրաստվում էր ճանապարհ ընկնել, երբ մեկը վազելով մոտեցավ, ծնկի գալով՝ նրան հարցրեց. «Բարի՛ վարդապետ, ի՞նչ պետք է անեմ, որ հավիտենական կյանքը ժառանգեմ»։","18":"Հիսուսը նրան ասաց. «Ինչո՞ւ ես ինձ \"բարի\" անվանում. ոչ ոք բարի չէ, բացի միայն մեկից՝ Աստծուց։","19":"Պատվիրանները գիտես. \"Մի՛ շնացիր, մի՛ սպանիր, մի՛ գողացիր, սուտ մի՛ վկայիր, ուրիշի ունեցածը մի՛ խլիր, քո հորն ու մորը պատվի՛ր\" (Ելք 20.14, 13, 15-17, 12, Բ Օր. 5.18, 17, 19-21, 16)»։","20":"Իսկ նա պատասխանեց. «Վարդապե՛տ, այդ բոլորն իմ մանկությունից ի վեր պահել եմ»։","21":"Հիսուսը սիրալիր նայեց նրան ու ասաց. «Քեզ մի բան է պակասում։ Եթե կամենում ես, գնա՛, ինչ որ ունես, վաճառի՛ր ու աղքատների՛ն բաժանիր և երկնքում գանձ կունենաս։ Վերցրո՛ւ խաչը և արի՛ իմ հետևից»։","22":"Բայց նա, այդ խոսքից մռայլվելով, տրտմած գնաց, որովհետև մեծ ունեցվածքի տեր էր։","23":"Եվ Հիսուսը, շուրջը նայելով, իր աշակերտներին ասաց. «Որքա՜ն դժվար է հարստություն ունեցողների համար Աստծու արքայությունը մտնել»։","24":"Աշակերտները զարմացած էին նրա խոսքերի վրա։ Սակայն Հիսուսն ասաց նրանց. «Որդյակնե՛ր, որքա՜ն դժվար է Աստծու արքայությունը մտնել նրանց համար, ովքեր իրենց հույսը հարստության վրա են դրել։","25":"Ավելի հեշտ է, որ ուղտն ասեղի ծակով անցնի, քան հարուստն Աստծու արքայությունը մտնի»։","26":"Աշակերտներն ավելի էին զարմանում և միմյանց ասում. «Հապա ո՞վ կարող է փրկվել»։","27":"Հիսուսը նրանց նայեց ու ասաց. «Մարդկանց համար դա անհնար է, բայց ո՛չ Աստծու համար։ Աստծու համար ամեն ինչ է հնարավոր»։","28":"Այդժամ Պետրոսն սկսեց նրան ասել. «Ահա մենք ամեն ինչ թողեցինք ու քո հետևից եկանք»։","29":"Հիսուսը պատասխանեց. «Ճշմարիտ եմ ասում ձեզ. չկա մեկը, որ ինձ համար կամ Ավետարանի համար թողնի տունը կամ եղբայրներին, կամ քույրերին, կամ հորը, կամ մորը, կամ կնոջը, կամ զավակներին, կամ արտերը,","30":"և հիմա՝ այս ժամանակ, չստանա հարյուրապատիկը՝ տներ ու եղբայրներ, քույրեր ու մայրեր, զավակներ ու արտեր՝ կրելով նաև հալածանքներ, իսկ հանդերձյալ աշխարհում էլ հավիտենական կյանք կունենա։","31":"Բայց շատերը, որ առաջինն են, վերջինը կլինեն, իսկ վերջինները՝ առաջինը»։","32":"Նրանք Երուսաղեմ բարձրանալու ճանապարհին էին։ Հիսուսը նրանցից առաջ ընկած գնում էր. աշակերտները զարմացած ու վախեցած նրան էին հետևում։ Հիսուսը տասներկուսին դարձյալ առանձնացրեց և սկսեց նրանց ասել, թե իրեն ինչե՛ր են պատահելու։","33":"«Ահա Երուսաղեմ ենք ելնում, և Մարդու Որդին կմատնվի քահանայապետների և դպիրների ձեռքը. նրան մահվան կդատապարտեն, նրան հեթանոսներին կհանձնեն։","34":"Նրան կծաղրեն, նրան կծեծեն, նրա վրա կթքեն ու կսպանեն նրան, և երրորդ օրը հարություն կառնի»։","35":"Եվ Զեբեդեոսի որդիները՝ Հակոբոսն ու Հովհաննեսը, մոտեցան նրան ու ասացին. «Վարդապե՛տ, ուզում ենք, որ այն, ինչ քեզանից խնդրելու ենք, անես մեզ համար»։","36":"Հիսուսը հարցրեց նրանց. «Ի՞նչ եք ուզում, որ ես ձեզ համար անեմ»։","37":"Նրանք ասացին նրան. «Մեզ շնո՛րհ արա, որ քո փառքի մեջ մեկս քո աջ կողմում նստի, մյուսս՝ քո ձախ կողմում»։","38":"Այդժամ Հիսուսը նրանց ասաց. «Չգիտեք, թե ի՛նչ եք խնդրում։ Կարո՞ղ եք այն բաժակը խմել, որ ես եմ խմելու, կամ այն մկրտությամբ մկրտվել, որով ես եմ մկրտվելու»։","39":"Նրանք ասացին նրան. «Կարող ենք»։ Իսկ Հիսուսը նրանց ասաց. «Այն բաժակը, որ ես եմ խմելու, կխմեք, և այն մկրտությամբ, որով ես եմ մկրտվելու, կմկրտվեք,","40":"բայց իմ աջ ու ձախ կողմերում նստելը ե՛ս չեմ տալիս, այլ տրվելու է նրանց, որոնց համար պատրաստված է»։","41":"Երբ մնացած տասը աշակերտները լսեցին այս, սկսեցին Հակոբոսի ու Հովհաննեսի վրա բարկանալ։","42":"Հիսուսը նրանց իր մոտ կանչեց ու ասաց. «Գիտեք, որ հեթանոսների մեջ ովքեր իշխան են համարվում, տիրում են նրանց, և նրանց մեծամեծները իշխում են նրանց վրա։","43":"Բայց ձեր մեջ այդպես չպետք է լինի, այլ ձեզանից ով ուզում է մեծ լինել, պետք է ձեր սպասավորը լինի։","44":"Եվ ձեզանից ով ուզում է առաջինը լինել, բոլորի ծառան պետք է լինի։","45":"Որովհետև Մարդու Որդին նույնպես չեկավ, որ իրեն ծառայեն, այլ որ ինքը ծառայի ու շատերի համար իր կյանքը որպես փրկագին տա»։","46":"Եկան Երիքով։ Երբ Հիսուսն իր աշակերտների ու մեծ բազմության հետ Երիքովից դուրս էր գալիս, Տիմեի որդին՝ կույր Բարտիմեոսը, ճանապարհին նստած, մուրում էր։","47":"Երբ լսեց, որ Հիսուս Նազովրեցին է անցնում, սկսեց աղաղակել ու ասել. «Որդի՛ Դավթի, Հիսո՛ւս, ողորմի՛ր ինձ»։","48":"Շատերը նրան սաստում էին, որ լուռ մնար, բայց նա է՛լ ավելի էր աղաղակում. «Որդի՛ Դավթի, ողորմի՛ր ինձ»։","49":"Հիսուսը կանգնեց ու ասաց, որ նրան կանչեն։ Կույրին կանչեցին ու ասացին նրան. «Քաջալերվի՛ր, վե՛ր կաց, քեզ կանչում է»։","50":"Նա իր վերնազգեստը դեն գցեց, վեր կացավ ու Հիսուսի մոտ եկավ։","51":"Հիսուսը նրան հարցրեց. «Ի՞նչ ես ուզում, որ քեզ համար անեմ»։ Կույրը պատասխանեց նրան. «Ռաբբո՛ւնի, ուզում եմ տեսնել»։","52":"Հիսուսը նրան ասաց. «Գնա՛, քո հավատը քեզ փրկեց»։ Եվ նրա տեսողությունն իսկույն վերականգնվեց, ու հետևեց Հիսուսին։"},"11":{"1":"Երբ մոտեցան Երուսաղեմին, Բեթփագեին ու Բեթանիային՝ Ձիթենյաց լեռան մոտ, Հիսուսն իր աշակերտներից երկուսին ուղարկեց","2":"և նրանց ասաց. «Գնացե՛ք դիմացի գյուղը և հենց այնտեղ մտնեք, մի կապված ավանակ կգտնեք, որի վրա դեռ ոչ ոք չի նստել. արձակե՛ք այն և բերե՛ք։","3":"Ու եթե որևէ մեկը ձեզ ասի՝ \"Ինչո՞ւ եք դա անում\", ասե՛ք, որ այն պետք է Տիրոջը, և նա այն իսկույն այստեղ կուղարկի»։","4":"Նրանք գնացին ու ավանակը գտան փողոցից դուրս մի դռան մոտ կապված և արձակեցին այն։","5":"Այնտեղ կանգնածներից ոմանք նրանց ասացին. «Այդ ի՞նչ եք անում, ինչո՞ւ եք այդ ավանակն արձակում»։","6":"Իսկ նրանք պատասխանեցին, ինչպես Հիսուսն էր կարգադրել, և թույլ տվեցին նրանց։","7":"Ավանակը Հիսուսի մոտ բերեցին, իրենց հագուստները վրան գցեցին, և նա նստեց ավանակի վրա։","8":"Շատերն իրենց հագուստները փռում էին ճանապարհին, ուրիշները ծառերից ճյուղեր էին կտրում ու ճանապարհին փռում։","9":"Եվ Հիսուսի առջևից ու հետևից գնացողները աղաղակում էին ու ասում. «Օվսաննա՜, օրհնյա՜լ է Տիրոջ անունով եկողը (Սաղ. 118.26).","10":"օրհնյա՜լ է մեր հոր՝ Դավթի թագավորությունը, որ գալիս է։ Օվսաննա՜ Բարձրյալին (հմմտ. եբր. Սաղ. 118.25)»։","11":"Հիսուսը մտավ Երուսաղեմ և տաճար գնաց։ Շուրջն ամեն ինչ աչքի անցկացնելուց հետո, քանի որ արդեն երեկո էր, տասներկու աշակերտների հետ գնաց Բեթանիա։","12":"Հետևյալ օրը, երբ Բեթանիայից դուրս էին գալիս, Հիսուսը քաղց զգաց։","13":"Հեռվից տերևաշատ մի թզենի տեսնելով՝ մոտեցավ, որ նրա վրա որևէ մի բան գտնի։ Բայց երբ մոտեցավ, տերևներից բացի ոչինչ չգտավ, որովհետև դեռ թզի ժամանակը չէր։","14":"Հիսուսն ասաց թզենուն. «Թող ոչ ոք այլևս քեզանից պտուղ չուտի հավիտյան»։ Նրա աշակերտները լսում էին։","15":"Եկան Երուսաղեմ։ Հիսուսը տաճար մտավ և սկսեց դուրս հանել տաճարում գտնվող վաճառողներին ու գնողներին։ Նա շուռ տվեց լումայափոխների սեղանները և կոտրեց աղավնեվաճառների աթոռները։","16":"Նա նաև թույլ չէր տալիս, որ որևէ մեկը տաճարի միջով որևէ բան տեղափոխեր։","17":"Եվ ուսուցանում էր ու ասում նրանց. «Գրված չէ՞, թե՝ \"Իմ տունը բոլոր ազգերի համար աղոթքի տուն պետք է կոչվի\" (Ես. 56.7)։ Իսկ դուք այն ավազակների որջ եք դարձրել»։","18":"Քահանայապետներն ու դպիրները լսեցին այս և միջոց էին փնտրում, թե ինչպե՛ս նրան կորստյան մատնեն, սակայն նրանից վախենում էին, քանի որ ամբողջ ժողովուրդը հիանում էր նրա ուսուցմամբ։","19":"Երբ երեկոն իջավ, Հիսուսն իր աշակերտների հետ քաղաքից դուրս ելավ։","20":"Առավոտյան նույն տեղով անցնելիս տեսան այն թզենին՝ արմատից չորացած։","21":"Եվ Պետրոսը հիշեց ու ասաց նրան. «Ռա՛բբի, տե՛ս այն թզենին, որին անիծեցիր, չորացել է»։","22":"Հիսուսը պատասխանեց ու ասաց նրանց. «Աստծու հանդեպ հավա՛տ ունեցեք։","23":"Ճշմարիտ եմ ասում ձեզ. ով այս լեռանն ասի. \"Ե՛լ ու ծո՛վն ընկիր\", ու իր սրտում չերկմտի, այլ հավատա, որ ինչ ասում է, կլինի, արդ ինչ որ ասի, կլինի։","24":"Դրա համար ասում եմ ձեզ. այն ամենը, ինչ աղոթքով խնդրեք, հավատացե՛ք, որ կստանաք, ու դա կտրվի ձեզ։","25":"Եվ երբ աղոթքի կանգնեք, եթե մեկի դեմ որևէ բան ունեք, ներե՛ք, որպեսզի ձեր Հայրն էլ, որ երկնքում է, ձեր հանցանքները ձեզ ների։","26":"Բայց եթե դուք չներեք, ձեր երկնավոր Հայրն էլ ձեր հանցանքները չի ների ձեզ»։","27":"Նրանք դարձյալ Երուսաղեմ եկան։ Մինչ Հիսուսը տաճարում քայլում էր, քահանայապետները, դպիրներն ու ծերերը մոտեցան նրան","28":"և հարցրին. «Ի՞նչ իշխանությամբ ես այդ բաներն անում, և ո՞վ է քեզ այդ իշխանությունը տվել, որ այդ բաներն անես»։","29":"Հիսուսը պատասխանեց ու նրանց ասաց. «Ես էլ ձեզ մի բան հարցնեմ, պատասխա՛ն տվեք ինձ, և ես ձեզ կասեմ, թե ի՛նչ իշխանությամբ եմ անում այս բաները։","30":"Հովհաննեսի մկրտությունը երկնքի՞ց էր, թե՞ մարդկանցից. պատասխա՛ն տվեք ինձ»։","31":"Նրանք իրար մեջ քննարկում էին ու ասում. «Եթե ասենք՝ երկնքից, կասի. \"Հապա ինչո՞ւ չհավատացիք նրան\"։","32":"Իսկ եթե ասենք՝ մարդկանցից, ժողովրդից ենք վախենում», որովհետև բոլորը Հովհաննեսին մարգարե էին համարում։","33":"Պատասխանեցին ու Հիսուսին ասացին. «Չգիտենք»։ Հիսուսն էլ նրանց ասաց. «Ես էլ ձե՛զ չեմ ասի, թե ի՛նչ իշխանությամբ եմ այս բաներն անում»։"},"12":{"1":"Հիսուսն սկսեց նրանց հետ առակներով խոսել. «Մի մարդ այգի տնկեց, ցանկապատեց այն, հնձան փորեց ու աշտարակ շինեց. այն տվեց մշակներին և ուրիշ երկիր գնաց։","2":"Երբ ժամանակը եկավ, մշակների մոտ մի ծառայի ուղարկեց, որ մշակներից այգու բերքից վերցնի։","3":"Իսկ նրանք բռնեցին նրան, ծեծեցին ու դատարկաձեռն ուղարկեցին։","4":"Դարձյալ մի ուրիշ ծառայի ուղարկեց նրանց մոտ, և քարկոծելով ջարդեցին նրա գլուխն ու անարգելով վռնդեցին։","5":"Եվ նորից ուրիշի ուղարկեց. սրան էլ սպանեցին։ Եվ այդպես շատ ուրիշների էլ ուղարկեց. ոմանց ծեծում էին, ոմանց՝ սպանում։","6":"Նա մի սիրելի որդի ուներ, որին վերջում ուղարկեց նրանց մոտ ու ասաց. \"Գուցե որդուցս ամաչեն\"։","7":"Բայց երբ մշակները տեսան, որ նա գալիս է, միմյանց ասացին. \"Սա է ժառանգը. եկեք նրան սպանենք, և ժառանգությունը մերը կլինի\"։","8":"Եվ նրան բռնեցին, սպանեցին ու այգուց դուրս նետեցին։","9":"Արդ այգու տերն ի՞նչ կանի. կգա ու մշակներին կորստյան կմատնի և այգին կտա ուրիշներին։","10":"Եվ դուք այն գրվածը չե՞ք կարդացել. \"Այն քարը, որ շինարարները որպես անպիտան մերժեցին, անկյունաքար եղավ\"։","11":"Տերը դա արեց, և մեր աչքերին սքանչելի է»։","12":"Եվ ուզում էին Հիսուսին բռնել, որովհետև հասկացան, որ այդ առակն իրենց մասին ասաց, բայց ժողովրդից վախեցան, թողեցին նրան ու գնացին։","13":"Եվ փարիսեցիներից ու հերովդեսականներից մի քանի հոգու նրա մոտ ուղարկեցին, որ խոսքով ծուղակը գցեն նրան։","14":"Նրանք եկան ու նրան ասացին. «Վարդապե՛տ, գիտենք, որ ճշմարիտ ես, և ոչ ոք քեզ հոգ չէ, որովհետև մարդկանց միջև խտրականություն չես դնում, այլ ճշմարտությամբ Աստծու ճանապարհն ես ուսուցանում։ Արդ ասա՛ մեզ, կայսրին հարկ տալն օրինավո՞ր է, թե՞ ոչ. տա՞նք, թե՞ չտանք»։","15":"Իսկ նա, նրանց կեղծավորությունը հասկանալով, ասաց նրանց. «Ինչո՞ւ եք ինձ փորձում. ինձ մի դահեկա՛ն բերեք, որ տեսնեմ»։","16":"Եվ նրանք բերեցին։ Եվ նրանց հարցրեց. «Այս պատկերը կամ գիրը ո՞ւմն է»։ Նրանք պատասխանեցին. «Կայսրինը»։","17":"Այդժամ Հիսուսը պատասխանեց ու ասաց նրանց. «Կայսրինը կայսրի՛ն տվեք, իսկ Աստծունը՝ Աստծուն»։ Եվ զարմացան նրա վրա։","18":"Նրա մոտ եկան սադուկեցիները, որոնք ասում են, թե հարություն չկա։ Նրան հարցրին ու ասացին.","19":"«Վարդապե՛տ, Մովսեսը մեզ համար գրել է, որ եթե մեկի եղբայրը մեռնի ու կին թողնի, բայց զավակներ չթողնի, նրա եղբայրը թող կնության առնի նրա կնոջն ու իր եղբոր համար զավակ ապահովի (Բ Օր. 25.5)։","20":"Ահա յոթ եղբայրներ կային. առաջինը կին առավ ու մեռնելուց հետո զավակ չթողեց։","21":"Երկրորդը նրան կնության առավ ու մեռավ, նա էլ զավակ չթողեց, նույն կերպ էլ երրորդը...","22":"Եվ այն յոթն էլ նրան կնության առան ու զավակ չթողեցին։ Իսկ բոլորից հետո կինը մեռավ։","23":"Արդ, հարության ժամանակ, երբ հարություն առնեն, կինը նրանցից որի՞նը կլինի. որովհետև յոթն էլ նրան կնության էին առել»։","24":"Հիսուսը պատասխանեց նրանց և ասաց. «Մոլորության մեջ եք ընկել, որովհետև ո՛չ Սուրբ Գիրքը գիտեք, ո՛չ Աստծու զորությունը։","25":"Որովհետև երբ մեռելներից հարություն առնեն, ո՛չ կին կառնեն, ո՛չ էլ մարդու կգնան, այլ կլինեն ինչպես հրեշտակները, որ երկնքում են։","26":"Սակայն մեռելների մասին, որ հարություն են առնելու, դուք Մովսեսի գրքում՝ մորենու դրվագի մեջ, չե՞ք կարդացել, թե Աստված ինչպե՛ս խոսեց նրա հետ ու ասաց. \"Ես եմ Աբրահամի Աստվածը, Իսահակի Աստվածը, Հակոբի Աստվածը\" (Ելք 3.6)։","27":"Նա մեռածների Աստվածը չէ, այլ ողջերի. ուրեմն դուք մեծ մոլորության մեջ եք գտնվում»։","28":"Դպիրներից մեկը, որ լսում էր նրանց վեճը և տեսավ, որ Հիսուսը սադուկեցիներին լավ պատասխանեց, մոտեցավ ու նրան հարցրեց. «Ո՞րն է ամենակարևոր պատվիրանը»։","29":"Հիսուսը նրան պատասխանեց. «Առաջին և ամենակարևոր պատվիրանը սա է՝ \"Լսի՛ր, Իսրայե՛լ, մեր Տերը՝ Աստված, միակ Տերն է։","30":"Եվ սիրի՛ր քո Տեր Աստծուն քո ամբողջ սրտով, ամբողջ հոգով, ամբողջ մտքով ու ամբողջ զորությամբ\" (Բ Օր. 6.4-5)։ Սա է առաջին պատվիրանը։","31":"Իսկ երկրորդը սրան նման է՝ \"Սիրի՛ր քո ընկերոջը քո անձի պես\" (Ղևտ. 19.18)։ Սրանցից ավելի մեծ պատվիրան չկա»։","32":"Եվ դպիրը նրան ասաց. «Լա՛վ, Վարդապե՛տ, ճշմարիտ ասացիր, որ Աստված մեկ է, նրանից բացի ուրիշը չկա։","33":"Եվ որ նրան ամբողջ սրտով, ամբողջ մտքով, ամբողջ էությամբ ու ամբողջ զորությամբ սիրելը և ընկերոջն իր անձի պես սիրելն առավել է, քան բոլոր ողջակեզներն ու զոհերը»։","34":"Եվ Հիսուսը, տեսնելով, որ նա իմաստությամբ պատասխանեց, նրան ասաց. «Դու Աստծու արքայությունից հեռու չես»։ Ու ոչ ոք այլևս չէր համարձակվում նրան որևէ բան հարցնել։","35":"Երբ Հիսուսն ուսուցանում էր տաճարում, ասաց. «Դպիրներն ինչպե՞ս են ասում, թե Քրիստոսը Դավթի որդին է։","36":"Դավիթն ինքը Սուրբ Հոգով ասում է. \"Տերն իմ Տիրոջն ասաց. \"Իմ աջ կողմո՛ւմ նստիր, մինչև որ քո թշնամիներին ոտքերիդ պատվանդան դնեմ\" (Սաղ. 110.1)։","37":"Արդ, եթե Դավիթն ինքը նրան Տեր է կոչում, հապա ինչպե՞ս կարող է նրա որդին լինել»։ Եվ մեծ բազմությունը հաճույքով նրան էր լսում։","38":"Հիսուսն իր ուսուցման մեջ նրանց ասում էր. «Զգուշացե՛ք դպիրներից, որոնց դուր է գալիս փառավոր հագուստներով ման գալ ու հրապարակներում հարգալից ողջույններ ընդունել,","39":"ժողովարաններում առաջին աթոռները զբաղեցնել, ընթրիքներին՝ առաջին տեղերը։","40":"Նրանք այրիների ունեցածն են ուտում ու ցուցադրաբար երկար աղոթք են անում։ Նրանք ավելի խիստ են պատժվելու»։","41":"Հիսուսը, գանձանակի դիմաց նստած, նայում էր, թե ժողովուրդն ինչպե՛ս էր գանձանակի մեջ փող գցում։ Շատ հարուստներ մեծ գումար էին գցում։","42":"Մի աղքատ այրի կին եկավ, երկու լումա գցեց, այսինքն՝ մի նաքարակիտ։","43":"Այդժամ Հիսուսն աշակերտներին իր մոտ կանչեց ու նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ այս աղքատ այրին ավելի շատ գցեց գանձանակի մեջ, քան մյուսները,","44":"որովհետև բոլորն իրենց ավելացածից գցեցին, մինչդեռ նա, չքավոր լինելով, գցեց այն, ինչ ուներ՝ իր ամբողջ ապրուստը»։"},"13":{"1":"Երբ նա տաճարից դուրս էր գալիս, աշակերտներից մեկը նրան ասաց. «Վարդապե՛տ, տես ինչպիսի՜ քարեր ու ինչպիսի՜ շինություններ են»։","2":"Հիսուսն ասաց նրան. «Տեսնո՞ւմ ես այդ մեծ շինությունները. այստեղ քարը քարի վրա չի թողնվելու, ամեն ինչ պիտի քանդվի»։","3":"Մինչ Հիսուսը նստած էր Ձիթենյաց լեռան վրա՝ տաճարի դիմաց, Պետրոսը, Հակոբոսը, Հովհաննեսն ու Անդրեասը նրան առանձին հարցրին.","4":"«Ասա՛ մեզ, ե՞րբ են դրանք լինելու, և ո՞րն է լինելու այն նշանը, որ կազդարարի այդ բոլոր բաների կատարումը»։","5":"Այդժամ Հիսուսը սկսեց նրանց ասել. «Զգուշացե՛ք, որ ոչ ոք ձեզ չխաբի։","6":"Շատերը իմ անունով կգան ու կասեն. \"Ես եմ Քրիստոսը\", և շատերին կմոլորեցնեն։","7":"Երբ լսեք, որ պատերազմներ են լինում կամ պատերազմներ են նախապատրաստվում, մի՛ խռովվեք, որովհետև դրանք պետք է լինեն։ Բայց դեռ վերջը չէ։","8":"Որովհետև ազգը ազգի դեմ կելնի, թագավորությունը՝ թագավորության դեմ, տեղ առ տեղ երկրաշարժեր կլինեն, սով ու խռովություններ կլինեն։ Սակայն սրանք նեղությունների սկիզբն են։","9":"Բայց դուք զգուշացե՛ք ձեր կյանքի համար. ձեզ դատարաններ կհանձնեն, ժողովարաններում ծեծի կենթարկվեք, իմ պատճառով կուսակալների ու թագավորների առաջ կտարվեք՝ իմ մասին նրանց վկայություն տալու։","10":"Նախ Ավետարանը պետք է քարոզվի բոլոր ազգերին։","11":"Երբ ձեզ տանեն դատարան հանձնելու, կանխավ մի՛ մտահոգվեք, թե ի՛նչ եք խոսելու, այլ այդ պահին ինչ որ ձեզ տրվի, ա՛յդ ասեք, որովհետև դուք չէ, որ պիտի խոսեք, այլ Սուրբ Հոգին։","12":"Եղբայրը եղբորը մահվան կմատնի, հայրը՝ որդուն, զավակները ծնողների դեմ կելնեն և նրանց կսպանեն։","13":"Եվ իմ անվան պատճառով բոլորը ձեզ կատեն։ Սակայն ով մինչև վերջ համբերի, նա կփրկվի։","14":"Ու երբ տեսնեք ավերածության պղծությունը,- որի մասին ասել է Դանիել մարգարեն (ով կարդում է, թող հասկանա),- որ կանգնել է ա՛յն տեղում, ուր չպետք է լիներ, այն ժամանակ ովքեր Հրեաստանում լինեն, թող սարերը փախչեն,","15":"ով տանիքի վրա լինի, թող չիջնի և մի բան վերցնելու համար տուն չմտնի,","16":"ով արտում լինի, թող իր վերարկուն վերցնելու համար հետ չդառնա։","17":"Բայց վա՛յ հղիներին ու ստնտուներին այն օրերին։","18":"Աղոթե՛ք, որ ձեր փախուստը ձմեռ ժամանակ չլինի։","19":"Որովհետև այդ օրերին կլինեն այնպիսի նեղություններ, ինչպիսիք արարչագործության սկզբից մինչև հիմա չեն եղել և ոչ էլ կլինեն։","20":"Եվ եթե Տերն այդ օրերը չպակասեցներ, ոչ ոք չէր փրկվի. սակայն ընտրյալների համար, որոնց ընտրեց, այն օրերը կարճացրեց։","21":"Եվ այն ժամանակ եթե մեկը ձեզ ասի՝ \"Ահա այստեղ է Քրիստոսը\" կամ \"Ահա այնտեղ է\", չհավատաք։","22":"Որովհետև կհայտնվեն սուտ քրիստոսներ ու սուտ մարգարեներ, որոնք նշաններ ու հրաշքներ ցույց կտան, որպեսզի մոլորեցնեն, եթե հնարավոր լինի, նույնիսկ ընտրյալներին։","23":"Բայց դուք զգո՛ւյշ եղեք. ահա նախապես ձեզ ամեն ինչ ասացի։","24":"Բայց այդ օրերին՝ այդ նեղություններից հետո, արեգակը կխավարի, լուսինն իր լույսը չի տա։","25":"Աստղերը երկնքից կընկնեն, ու երկնային զորությունները կսասանվեն։","26":"Այն ժամանակ կտեսնեն Մարդու Որդուն, որ գալիս է ամպերի վրայով (Դան. 7.13) մեծ զորությամբ ու փառքով։","27":"Այն ժամանակ նա կուղարկի իր հրեշտակներին և կհավաքի իր ընտրյալներին չորս կողմերից՝ երկրի ծայրից մինչև երկնքի ծայրը։","28":"Բայց դաս առեք թզենո՛ւ օրինակից. երբ նրա ճյուղերն արդեն փափկում են ու տերևներ են արձակում, իմանում եք, որ ամառը մոտ է։","29":"Այդպես էլ դուք. երբ տեսնեք, որ այս ամենը տեղի է ունենում, իմացե՛ք, որ վերջը մոտեցել է։","30":"Ճշմարիտ եմ ասում ձեզ, որ մինչ այս սերունդը ապրում է, այս ամենը տեղի կունենա։","31":"Երկինքն ու երկիրը կանցնեն, բայց իմ խոսքերը չեն անցնի։","32":"Սակայն այդ օրվա ու ժամի մասին ոչ ոք չգիտի՝ ո՛չ հրեշտակները երկնքում, ո՛չ էլ Որդին, այլ միայն Հայրը։","33":"Զգո՛ւյշ եղեք, արթո՛ւն մնացեք ու աղոթե՛ք, որովհետև չգիտեք, թե ժամանակը ե՛րբ է գալու։","34":"Ինչպես այն մարդը, որ հեռու աշխարհ գնալիս իր տունը կթողնի, իր ծառաներին իշխանություն կտա, յուրաքանչյուրի համար իր գործը կսահմանի, իսկ դռնապանին կհրամայի, որ արթուն մնա։","35":"Արդ, արթո՛ւն կացեք, քանի որ չգիտեք, թե տանտերը ե՛րբ կգա՝ երեկոյա՞ն, թե՞ կեսգիշերին, աքլորականչի՞ն, թե՞ առավոտյան։","36":"Չլինի թե հանկարծակի գա և ձեզ քնած գտնի։","37":"Եվ ինչ որ ձեզ ասում եմ, բոլորին եմ ասում՝ արթո՛ւն կացեք»։"},"14":{"1":"Երկու օր հետո Զատկի և Բաղարջակերաց տոնն էր։ Քահանայապետներն ու դպիրները միջոց էին փնտրում, թե ինչպե՛ս Հիսուսին նենգությամբ բռնեն և սպանեն։","2":"Բայց ասում էին. «Ո՛չ տոնի ժամանակ, որպեսզի ժողովրդի մեջ խռովություն չլինի»։","3":"Մինչ Հիսուսը Բեթանիայում էր, բորոտ Սիմոնի տանը սեղան նստած, եկավ մի կին, որն ուներ նարդոսի ազնիվ, թանկագին յուղի մի շիշ. նա շիշը կոտրեց և Հիսուսի գլխին թափեց։","4":"Սակայն ոմանք սրտնեղեցին՝ ասելով. «Ինչի՞ համար էր յուղի այս վատնումը,","5":"որովհետև այն կարելի էր երեք հարյուր դինարից ավելի թանկ վաճառել ու աղքատներին տալ»։ Եվ հանդիմանում էին այդ կնոջը։","6":"Հիսուսն ասաց. «Թողե՛ք նրան, ինչո՞ւ եք նեղացնում։ Նա ինձ համար մի բարի գործ արեց։","7":"Աղքատները միշտ ձեզ հետ են. երբ ուզեք, նրանց կարող եք բարիք անել, բայց ինձ միշտ ձեզ հետ չեք ունենա։","8":"Նա արեց, ինչ որ կարող էր. նախօրոք օծեց իմ մարմինը՝ թաղմանը նախապատրաստելու համար։","9":"Ճշմարիտ եմ ասում ձեզ. ամբողջ աշխարհում, որտեղ որ այս Ավետարանը քարոզվի, ի հիշատակ նրա՝ այդ արարքի մասին էլ կպատմվի»։","10":"Ապա Հուդա Իսկարիովտացին՝ տասներկուսից մեկը, քահանայապետների մոտ գնաց, որպեսզի Հիսուսին մատնի նրանց։","11":"Երբ նրանք լսեցին, ուրախացան ու խոստացան նրան արծաթադրամ տալ։ Եվ Հուդան հարմար առիթ էր փնտրում, թե ինչպե՛ս մատներ նրան։","12":"Բաղարջակերաց տոնի առաջին օրը, երբ զատկական գառն էին մորթում, աշակերտներն ասացին Հիսուսին. «Որտե՞ղ ես ուզում ուտել զատկական ընթրիքը, որ գնանք պատրաստենք»։","13":"Հիսուսն աշակերտներից երկուսին ուղարկեց ու նրանց ասաց. «Գնացե՛ք քաղաք, և ջրով սափորը ձեռքին մի մարդ կհանդիպի ձեզ. գնացե՛ք նրա հետևից։","14":"Եվ ուր որ մտնի, այդ տան տիրոջն ասե՛ք. \"Վարդապետն ասում է. \"Որտե՞ղ է այն օթևանը, որտեղ աշակերտներիս հետ պիտի ուտեմ զատկական ընթրիքը\"։","15":"Նա ձեզ մի մեծ վերնատուն ցույց կտա՝ հարդարված, պատրաստ. այնտե՛ղ կպատրաստեք մեզ համար»։","16":"Աշակերտները գնացին քաղաք ու ամեն ինչ գտան այնպես, ինչպես իրենց ասել էր Հիսուսը, և պատրաստեցին զատկական ընթրիքը։","17":"Երբ երեկո եղավ, Հիսուսը տասներկուսի հետ եկավ։","18":"Մինչ սեղան էին նստել և ուտում էին, Հիսուսն ասաց. «Ճշմարիտ եմ ասում ձեզ, որ ձեզանից մեկը, ով ինձ հետ ուտում է, կմատնի ինձ»։","19":"Նրանք տրտմեցին ու սկսեցին մեկը մյուսի հետևից նրան հարցնել. «Մի՞թե ես եմ», և մյուսը՝ «Մի՞թե ես եմ»։","20":"Հիսուսն ասաց նրանց. «Տասներկուսիցդ նա, ով ձեռքն ինձ հետ պնակի մեջ մտցրեց։","21":"Արդարև, Մարդու Որդին կգնա, ինչպես նրա մասին գրված է. սակայն վա՛յ այն մարդուն, որի ձեռքով կմատնվի Մարդու Որդին։ Այդ մարդու համար ավելի լավ կլիներ, եթե ծնված չլիներ»։","22":"Եվ երբ նրանք ուտում էին, Հիսուսը վերցրեց հացը, օրհնեց, կտրեց ու նրանց տվեց՝ ասելով. «Առեք կերե՛ք, ա՛յս է իմ մարմինը»։","23":"Ապա վերցրեց բաժակը, գոհություն հայտնելով՝ նրանց տվեց, և բոլորն էլ խմեցին դրանից։","24":"Եվ նրանց ասաց. «Այս է նոր ուխտի իմ արյունը, որ թափվում է շատերի համար։","25":"Ճշմարիտ եմ ասում ձեզ, որ այլևս որթատունկի բերքից չեմ խմելու մինչև այն օրը, երբ նորը կխմեմ Աստծու արքայության մեջ»։","26":"Եվ սաղմոսելուց հետո ելան Ձիթենյաց լեռը։","27":"Հիսուսը նրանց ասաց. «Այս գիշեր դուք բոլորդ գայթակղվելու եք, որովհետև գրված է. \"Հովվին կհարվածեմ, և ոչխարները կցրվեն\"։","28":"Բայց իմ հարություն առնելուց հետո ձեզանից առաջ Գալիլեա կգնամ»։","29":"Պետրոսը նրան ասաց. «Թեկուզ բոլորն էլ գայթակղվեն, բայց ես չեմ գայթակղվի»։","30":"Հիսուսը նրան ասաց. «Ճշմարիտ եմ ասում քեզ, որ այսօր՝ հենց այս գիշեր, դեռ աքաղաղը երկու անգամ չկանչած, դու երեք անգամ կուրանաս ինձ»։","31":"Բայց Պետրոսն առավել ևս պնդում էր և ասում. «Ես քեզ չեմ ուրանա, եթե նույնիսկ հարկ լինի քեզ հետ մեռնել»։ Նույնը նաև բոլորն էին ասում։","32":"Եկան մի տեղ, որ Գեթսեմանի էր կոչվում։ Հիսուսն իր աշակերտներին ասաց. «Նստե՛ք այստեղ, մինչև աղոթեմ»։","33":"Եվ նա իր հետ վերցրեց Պետրոսին, Հակոբոսին ու Հովհաննեսին. սկսեց տագնապել ու տխրել։","34":"Այդժամ նրանց ասաց. «Հոգիս մահու չափ տրտմած է. այստե՛ղ մնացեք ու արթո՛ւն կացեք»։","35":"Եվ փոքր-ինչ առաջ գնաց, երեսնիվայր գետնին ընկավ և աղոթում էր, որ եթե հնարավոր է, այդ ժամն իրենից հեռանա։","36":"Եվ ասում էր. «Աբբա՛, Հա՛յր, քեզ համար ամեն ինչ հնարավոր է. այս բաժակն ինձանից հեռացրո՛ւ, բայց թող չլինի, ինչպես որ ես եմ կամենում, այլ ինչպես որ դու»։","37":"Ապա Հիսուսը եկավ և նրանց քնած գտավ։ Պետրոսին ասաց. «Սիմո՛ն, ննջո՞ւմ ես, չկարողացա՞ր մի ժամ արթուն մնալ։","38":"Արթո՛ւն կացեք ու աղո՛թք արեք, որ փորձության մեջ չընկնեք։ Հոգին հոժար է, բայց մարմինը՝ տկար»։","39":"Եվ դարձյալ գնաց, աղոթեց՝ նույն խոսքերն ասելով։","40":"Վերադարձավ և նրանց կրկին քնած գտավ, որովհետև նրանց աչքերը ծանրացել էին, ու չգիտեին՝ նրան ի՛նչ պատասխանեին։","41":"Երրորդ անգամ եկավ ու նրանց ասաց. «Դուք դեռ քնա՞ծ եք և հանգստանո՞ւմ եք։ Բավական է։ Ժամը եկավ, և ահա Մարդու Որդին մեղավորների ձեռքն է մատնվում։","42":"Վե՛ր կացեք գնանք. ահա ինձ մատնողը մոտեցավ»։","43":"Եվ շուտով, երբ նա դեռ խոսում էր, եկավ Հուդան՝ տասներկուսից մեկը, և նրա հետ կար սրերով ու մահակներով զինված մի ամբոխ՝ ուղարկված քահանայապետների, դպիրների ու ծերերի կողմից։","44":"Նրան մատնողը նրանց նշան էր տվել և ասել. «Ում համբուրեմ, նա է. նրան բռնե՛ք ու զգուշությամբ տարե՛ք»։","45":"Հուդան իսկույն եկավ, մոտեցավ նրան ու ասաց. «Ռա՛բբի, Ռա՛բբի», և նրան համբուրեց։","46":"Նրանք բռնեցին Հիսուսին և ձերբակալեցին նրան։","47":"Ապա նրա մոտ գտնվողներից մեկը սուրը քաշեց, զարկեց քահանայապետի ծառային և նրա ականջը կտրեց։","48":"Հիսուսն ասաց նրանց. «Սրերով ու մահակներով իմ դեմ ելաք որպես ավազակի՞, որ ձերբակալեք ինձ։","49":"Ամեն օր ձեզ մոտ էի, ուսուցանում էի տաճարում, և ինձ չձերբակալեցիք. բայց այսպես եղավ, որպեսզի կատարվեն գրվածքները»։","50":"Եվ ամենքը նրան թողեցին ու փախան։","51":"Մի երիտասարդ էր նրա հետևից գնում՝ մերկ մարմնին սավան փաթաթած։ Նրան բռնեցին։","52":"Իսկ նա սավանը թողեց ու մերկ փախավ նրանցից։","53":"Եվ Հիսուսին քահանայապետի մոտ տարան, և բոլոր քահանայապետները, ծերերն ու դպիրները այնտեղ էին հավաքվել։","54":"Պետրոսը, հեռվից նրան հետևելով, գնաց մինչև քահանայապետի պալատի գավթի ներսը. սպասավորների հետ նստել էր այնտեղ ու կրակի մոտ տաքանում էր։","55":"Քահանայապետներն ու ամբողջ ատյանը Հիսուսի դեմ որևէ վկայություն էին փնտրում, որ նրան սպանեն, սակայն չէին գտնում։","56":"Շատերն էին նրա դեմ սուտ վկայություն տալիս, բայց վկայությունները չէին համընկնում։","57":"Ոմանք վեր կացան, նրա դեմ սուտ վկայեցին՝ ասելով.","58":"«Մենք նրանից լսեցինք, որ ասում էր. \"Ես այդ ձեռակերտ տաճարը կքանդեմ ու երեք օրում մեկ ուրիշը՝ անձեռակերտը, կկառուցեմ\"»։","59":"Սակայն նրանց վկայությունները չէին համընկնում։","60":"Ապա քահանայապետը, մեջտեղում կանգնելով, Հիսուսին հարցրեց. «Ոչինչ չե՞ս պատասխանում. նրանք քո դեմ այս ի՞նչ են վկայում»։","61":"Իսկ նա լռում էր ու ոչինչ չէր պատասխանում։ Քահանայապետը կրկին նրան հարցրեց. «Դո՞ւ ես Քրիստոսը՝ Օրհնյալ Աստծու Որդին»։","62":"Հիսուսը պատասխանեց. «Ես եմ։ Եվ դուք պիտի տեսնեք Մարդու Որդուն՝ նստած Զորության աջ կողմում և երկնքի ամպերով գալիս (Դան. 7.13)»։","63":"Եվ քահանայապետը, իր պատմուճանը պատռելով, ասաց. «Այլևս կարիք ունե՞նք վկաների։","64":"Դուք լսեցիք հայհոյությունը. ձեզ ինչպե՞ս է թվում»։ Եվ բոլորը դատապարտեցին նրան. հանցավոր է և պետք է մահապատժի ենթարկվի։","65":"Ոմանք սկսեցին թքել նրա վրա, երեսը ծածկել ու բռունցքով նրան հարվածել և հարցնել. «Մարգարեացի՛ր մեզ, ո՞վ քեզ խփեց»։ Սպասավորները ևս ապտակում էին նրան։","66":"Մինչ Պետրոսը ներքևում՝ գավթում էր, քահանայապետի աղախիններից մեկը եկավ","67":"և տեսավ Պետրոսին, որ տաքանում էր. նայեց նրան ու ասաց. «Դու էլ էիր Հիսուս Նազովրեցու հետ»։","68":"Նա ուրացավ ու ասաց. «Ո՛չ գիտեմ և ո՛չ էլ հասկանում եմ, թե դու ի՛նչ ես ասում»։ Նա նախագավիթ դուրս եկավ, և աքաղաղը կանչեց։","69":"Աղախինը տեսավ նրան և այնտեղ գտնվողներին դարձյալ սկսեց ասել. «Սա էլ է նրանցից»։","70":"Բայց Պետրոսը դարձյալ ուրացավ։ Քիչ հետո այնտեղ գտնվողները Պետրոսին դարձյալ ասացին. «Իրապես որ դու էլ ես նրանցից, որովհետև գալիլեացի ես, և քո խոսվածքն էլ նման է»։","71":"Պետրոսը սկսեց նզովել ու երդվել. «Ես չեմ ճանաչում այն մարդուն, որի մասին դուք խոսում եք»։","72":"Եվ աքաղաղը երկրորդ անգամ կանչեց։ Այդժամ Պետրոսը հիշեց այն խոսքը, որ Հիսուսն ասել էր իրեն. «Աքաղաղը դեռ երկու անգամ չկանչած՝ դու ինձ երեք անգամ կուրանաս»։ Եվ սկսեց լաց լինել։"},"15":{"1":"Վաղ առավոտյան քահանայապետները, ծերերի, դպիրների և ամբողջ ատյանի հետ խորհրդակցելով, Հիսուսին կապեցին ու տարան հանձնեցին Պիղատոսին։","2":"Պիղատոսը նրան հարցրեց. «Դո՞ւ ես հրեաների թագավորը»։ Հիսուսը պատասխանեց ու ասաց նրան. «Դո՛ւ ես ասում»։","3":"Եվ քահանայապետները նրա դեմ շատ ամբաստանություններ էին անում։","4":"Պիղատոսը նրան դարձյալ հարցրեց ու ասաց. «Ոչ մի պատասխան չե՞ս տալիս. տես ինչքա՛ն են քեզ ամբաստանում»։","5":"Բայց Հիսուսը դարձյալ ոչինչ չպատասխանեց, այնպես որ Պիղատոսը զարմացավ։","6":"Ամեն Զատկի տոնին Պիղատոսը նրանց համար մի բանտարկյալ էր արձակում, ում համար որ նրանք խնդրում էին։","7":"Բարաբբա անունով մեկը կար՝ բանտարկված այն խռովարարների հետ, որոնք խռովության ժամանակ մարդ էին սպանել։","8":"Ամբոխն սկսեց բարձրաձայն աղաղակել ու պահանջել, որ Պիղատոսն անի այն, ինչ միշտ անում էր իրենց համար։","9":"Պիղատոսը նրանց հարցրեց. «Ուզո՞ւմ եք՝ հրեաների թագավորին արձակեմ ձեզ համար».","10":"որովհետև նա գիտեր, որ քահանայապետները նախանձից էին հանձնել նրան։","11":"Բայց քահանայապետներն ամբոխին գրգռեցին, որ պահանջեն՝ Բարաբբային իրենց համար արձակի։","12":"Պիղատոսը դարձյալ հարցրեց նրանց ու ասաց. «Ապա ի՞նչ եք ուզում, որ անեմ նրան, ում հրեաների թագավոր եք ասում»։","13":"Նրանք դարձյալ աղաղակեցին. «Խաչի՛ր նրան»։","14":"Պիղատոսը նրանց ասաց. «Ի՞նչ չար բան է արել»։ Սակայն նրանք ավելի ուժեղ էին աղաղակում. «Խաչի՛ր նրան»։","15":"Քանի որ Պիղատոսը ցանկանում էր գոհացնել ամբոխին, նրանց համար ազատ արձակեց Բարաբբային, իսկ Հիսուսին խարազանել տվեց և հանձնեց նրանց, որ խաչը հանվի։","16":"Զինվորները Հիսուսին տարան ներսի գավիթը, որտեղ դատարանն էր, և կանչեցին ամբողջ գնդին։","17":"Նրան ծիրանի հագցրին ու գլխին փշերից հյուսված պսակ դրեցին։","18":"Ապա սկսեցին նրան ողջույն տալ. «Ողջո՛ւյն, հրեաների՛ թագավոր»։","19":"Եղեգով հարվածում էին նրա գլխին, թքում նրա վրա և ծնկի գալով երկրպագում էին նրան։","20":"Նրան ծաղրելուց հետո վրայից հանեցին ծիրանին, իր հագուստները հագցրին և դուրս տարան, որպեսզի խաչեն նրան։","21":"Եվ ստիպեցին մի անցորդի՝ Սիմոն Կյուրենացուն՝ Ալեքսանդրի ու Ռուփոսի հորը, որը գալիս էր արտից, որ կրի Հիսուսի խաչափայտը։","22":"Եվ նրան տարան Գողգոթա, մի տեղ, որ «Գագաթ» է նշանակում։","23":"Նրան զմուռս խառնած գինի տվեցին, որ խմի, բայց նա չվերցրեց։","24":"Ապա նրան խաչեցին և նրա հագուստները բաժանեցին՝ դրանց վրա վիճակ գցելով, թե ով ի՛նչ պիտի վերցնի։","25":"Երրորդ ժամն էր, երբ նրան խաչեցին։","26":"Եվ գրված էր նրա հանցանքի պատճառը՝ «ՀՐԵԱՆԵՐԻ ԹԱԳԱՎՈՐԸ»։","27":"Հիսուսի հետ խաչեցին երկու ավազակների. մեկին՝ նրա աջ կողմում, իսկ մյուսին՝ ձախ կողմում։","28":"Այսպիսով կատարվեց Սուրբ Գրքում գրվածը, որ ասում էր. «Անօրենների շարքը դասվեց»։","29":"Անցորդները հայհոյում էին նրան և իրենց գլուխները շարժելով՝ ասում. «Վա՛հ, դու, որ քանդում էիր տաճարը և երեք օրում կառուցում։","30":"Փրկի՛ր քո անձը ու իջի՛ր խաչից»։","31":"Նույնպես էլ քահանայապետները դպիրների հետ իրար մեջ ծաղրում էին ու ասում. «Ուրիշներին փրկեց, իր անձը չի կարողանում փրկել։","32":"Ասում է՝ Քրիստոսն է՝ Իսրայելի թագավորը. թող հիմա խաչից իջնի, որ տեսնենք ու հավատանք նրան»։ Նրա հետ խաչվածներն էլ էին նրան նախատում։","33":"Վեցերորդ ժամին ամբողջ երկրի վրա խավարը տիրեց մինչև իններորդ ժամը։","34":"Իններորդ ժամին Հիսուսը բարձրաձայն աղաղակեց ու ասաց. «Էլի՛, Էլի՛, լա՞մա սաբաքթանի», որ թարգմանվում է՝ «Աստվա՛ծ իմ, Աստվա՛ծ իմ, ինչո՞ւ լքեցիր ինձ» (Սաղ. 22.1)։","35":"Այնտեղ գտնվողներից ոմանք, երբ լսեցին այս, ասում էին. «Ահա Եղիային է կանչում»։","36":"Մեկն առաջ վազեց, սպունգը քացախի մեջ թրջեց, եղեգի վրա դրեց և Հիսուսին տվեց, որ խմի, ասելով. «Թողեք տեսնենք՝ Եղիան կգա՞, որ նրան խաչից իջեցնի»։","37":"Ապա Հիսուսը բարձր ձայն արձակեց ու հոգին ավանդեց։","38":"Եվ տաճարի վարագույրը վերևից ներքև երկու մասի պատռվեց։","39":"Հարյուրապետը, որ կանգնած էր այնտեղ՝ նրա դիմաց, տեսնելով, թե ինչպես Հիսուսն աղաղակելով հոգին ավանդեց, ասաց. «Այս մարդն իսկապես որ Աստծու Որդին էր»։","40":"Այնտեղ կային նաև կանայք, որոնք հեռվից նայում էին։ Նրանց մեջ էին Մարիամ Մագդաղենացին, կրտսեր Հակոբոսի ու Հովսեսի մայրը՝ Մարիամը, և Սալոմեն։","41":"Նրանք ևս, երբ Հիսուսը Գալիլեայում էր, գնում էին նրա հետևից ու ծառայում նրան։ Ուրիշ շատ կանայք էլ կային, որոնք նրա հետ Երուսաղեմ էին բարձրացել։","42":"Երբ երեկո եղավ, քանի որ ուրբաթ էր՝ շաբաթ օրվա նախօրեն,","43":"եկավ Արիմաթեացի Հովսեփը, որը խորհրդի երևելի անդամ էր և ինքն էլ էր Աստծու արքայությանն սպասում։ Նա համարձակվեց Պիղատոսի մոտ մտնել և խնդրել Հիսուսի մարմինը։","44":"Պիղատոսը զարմացավ, որ Հիսուսն արդեն մեռել էր։ Նա հարյուրապետին իր մոտ կանչեց, նրան հարցրեց ու ասաց. «Վաղո՞ւց է, որ մեռել է»։","45":"Եվ հարյուրապետից տեղեկանալով՝ մարմինը Հովսեփին շնորհեց։","46":"Հովսեփը կտավ գնեց, Հիսուսին իջեցրեց, կտավով պատեց ու նրան մի ժայռափոր գերեզմանի մեջ դրեց։ Ապա նա գերեզմանի մուտքին մի քար գլորեց։","47":"Մարիամ Մագդաղենացին ու Հովսեսի մայր Մարիամը տեսան այն տեղը, ուր նա դրվեց։"},"16":{"1":"Եվ երբ շաբաթն անցավ, Մարիամ Մագդաղենացին, Հակոբոսի մայր Մարիամն ու Սալոմեն խունկեր գնեցին, որ գնան և օծեն Հիսուսի մարմինը։","2":"Եվ շաբաթվա առաջին օրը վաղ առավոտյան՝ արևածագին, գնացին գերեզման։","3":"Եվ միմյանց ասում էին. «Գերեզմանի մուտքից մեզ համար քարը ո՞վ կգլորի»։","4":"Բայց նայեցին ու տեսան, որ քարը գերեզմանից մի կողմ էր գլորված. այն շատ մեծ էր։","5":"Գերեզման մտան և մի երիտասարդի տեսան՝ աջ կողմում նստած, հագին սպիտակ պատմուճան, և վախեցան։","6":"Եվ նա ասաց նրանց. «Մի՛ վախեցեք. դուք Հիսուս Նազովրեցո՞ւն եք փնտրում, խաչվածի՞ն. նա հարություն առավ, այստեղ չէ։ Ահա այն տեղը, ուր դրել էին նրան։","7":"Բայց գնացե՛ք, նրա աշակերտներին ու Պետրոսին ասացե՛ք, որ նա ձեզանից առաջ գնում է Գալիլեա. այնտեղ կտեսնեք նրան, ինչպես որ ձեզ ասել էր»։","8":"Կանայք իսկույն դուրս ելան և փախան գերեզմանից. նրանք ահուդողի մեջ էին և ոչ ոքի ոչինչ չասացին, որովհետև վախենում էին։","9":"Հիսուսը հարություն առնելուց հետո՝ շաբաթվա առաջին օրվա առավոտյան, նախ երևաց Մարիամ Մագդաղենացուն, որից յոթ դև էր հանել։","10":"Մարիամը գնաց և պատմեց Հիսուսի հետ եղածներին, որ սգում էին ու լաց լինում։","11":"Իսկ երբ նրանք լսեցին, որ Հիսուսը ողջ է ու երևացել է նրան, չհավատացին։","12":"Հետո Հիսուսը այլ կերպարանքով երևաց նրանց, ովքեր արտ էին գնում։","13":"Նրանք ևս գնացին և մյուսներին պատմեցին, բայց ոչ էլ նրանց հավատացին։","14":"Վերջում, երբ տասնմեկ աշակերտները սեղան էին նստել, Հիսուսը երևաց նրանց և հանդիմանեց նրանց իրենց անհավատության ու քարսրտության համար, որ չհավատացին նրանց, ովքեր իրեն տեսել էին հարություն առած։","15":"Ապա նրանց ասաց. «Գնացե՛ք ամբողջ աշխարհով մեկ և բոլոր արարածներին Ավետարա՛նը քարոզեք։","16":"Ով հավատա ու մկրտվի, կփրկվի, իսկ ով չհավատա, կդատապարտվի։","17":"Նրանք, ովքեր կհավատան, ահա այս նշանները կանեն. իմ անունով դևեր կհանեն, նոր լեզուներով կխոսեն,","18":"ձեռքով օձեր կբռնեն ու եթե որևէ մահացու թույն խմեն, չեն վնասվի. հիվանդների վրա ձեռք կդնեն ու նրանց կբժշկեն»։","19":"Արդ Տերը նրանց հետ խոսելուց հետո երկինք համբարձվեց և նստեց Աստծու աջ կողմում։","20":"Իսկ նրանք գնացին և քարոզում էին ամենուր Տիրոջ գործակցությամբ և իրենց խոսքը հաստատում էին այն նշաններով, որ ուղեկցում էին իրենց։ Ամեն։"}};
